/*
 * MODERN LUDO + SNAKES & LADDERS
 * C11 + raylib
 *
 * LUDO
 *   - 2 Players
 *   - 4 Players
 *   - Team Mode (4 players, Red+Blue vs Green+Yellow)
 *   - VS Computer (Red vs Blue computer)
 *   - No snakes / ladders in Ludo
 *
 * SNAKES & LADDERS (separate 10x10 board)
 *   - 2 Players
 *   - VS Computer
 *
 * PLAY ON WIFI / HOTSPOT  (NO INTERNET NEEDED)
 *   - Ludo 2 Players, Ludo 4 Players, Ludo Team 2v2, Snakes & Ladders 2P
 *   - One person is the HOST (menu: PLAY ON WIFI > HOST ...).
 *     The host screen shows the host's IP address.
 *   - The other players choose PLAY ON WIFI > JOIN A GAME and type that IP.
 *   - Everyone must be on the same Wi-Fi, or connected to the same
 *     phone hotspot (or the PC's own hotspot).
 *   - Port used: 7777 (TCP). Allow the game in the firewall if asked.
 *   - Seats: host = Player 1 (RED). Joiners get the next seats in the
 *     order they connect (2P: BLUE | 4P: GREEN, BLUE, YELLOW).
 *
 * Sounds are generated by the program itself (no asset files needed).
 * Press M anywhere to mute / unmute.
 *
 * Windows / w64devkit:
 * gcc main.c -o ludo.exe -IC:/raylib/raylib/src -LC:/raylib/raylib/src -lraylib -lopengl32 -lgdi32 -lwinmm -lws2_32
 *
 * Linux:
 * gcc main.c -o ludo $(pkg-config --cflags --libs raylib) -lm
 */

#define _DEFAULT_SOURCE

#include "raylib.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

/* ---- networking headers ----
   They must come AFTER raylib.h. On Windows, NOGDI / NOUSER stop the
   Windows headers from clashing with raylib names (Rectangle, DrawText,
   CloseWindow, ShowCursor ...). */
#if defined(_WIN32)
    #define WIN32_LEAN_AND_MEAN
    #define NOGDI
    #define NOUSER
    #define NOMINMAX
    #include <winsock2.h>
    #include <ws2tcpip.h>
    typedef SOCKET NetSock;
    typedef int NetLen;
    #define NET_INVALID INVALID_SOCKET
    #define NET_SEND_FLAGS 0
#else
    #include <sys/types.h>
    #include <sys/socket.h>
    #include <sys/select.h>
    #include <netinet/in.h>
    #include <netinet/tcp.h>
    #include <arpa/inet.h>
    #include <net/if.h>
    #include <ifaddrs.h>
    #include <unistd.h>
    #include <fcntl.h>
    #include <errno.h>
    typedef int NetSock;
    typedef socklen_t NetLen;
    #define NET_INVALID (-1)
    #ifndef MSG_NOSIGNAL
        #define MSG_NOSIGNAL 0
    #endif
    #define NET_SEND_FLAGS MSG_NOSIGNAL
#endif

