/* ================================================================
   NETWORK STATE (types + globals; the socket code is further below)
   ================================================================ */

typedef enum { NET_OFF = 0, NET_HOST, NET_CLIENT } NetRole;

typedef enum {
    NP_NONE = 0,
    NP_HOST_WAIT,       /* host: waiting for friends to join       */
    NP_JOIN_INPUT,      /* client: typing the host IP              */
    NP_CONNECTING,      /* client: connecting                      */
    NP_CLIENT_WAIT,     /* client: connected, waiting for host     */
    NP_PLAYING          /* game running                            */
} NetPhase;

enum {
    MSG_HELLO = 1,      /* host -> client: seat, kind, count, teams */
    MSG_SNAP = 2,       /* host -> client: full game snapshot       */
    MSG_ROLL = 3,       /* client -> host: roll the dice            */
    MSG_PICK = 4,       /* client -> host: move token N             */
    MSG_RESTART = 5     /* client -> host: restart the game         */
};

typedef struct {
    NetSock sock;
    bool used;
    unsigned char rx[NET_RX_SIZE];
    int rxLen;
    unsigned char tx[NET_TX_SIZE];
    int txLen;
} NetConn;

typedef struct {
    NetRole role;
    NetPhase phase;
    NetSock listenSock;
    NetConn conns[NET_MAX_CLIENTS];   /* host: one per client, client: [0] = host */

    int seat;                         /* my seat (0 = host) */
    int hostKind;                     /* KIND_LUDO / KIND_SNAKES */
    int hostCount;                    /* number of players */
    bool hostTeams;

    float sendTimer;
    float connectTimer;

    char ip[24];                      /* IP typed by the joining player */
    int ipLen;

    char localIps[NET_MAX_IPS][24];   /* host: addresses to show */
    int localIpCount;

    char notice[96];
    float noticeTimer;

    bool wsReady;
} NetState;

static NetState gNet;
static unsigned char gSfxOut[NET_MAX_CLIENTS];   /* sounds to forward to clients */

/* Seat <-> player id helpers.
   Ludo : seat i plays game->order[i]     (2P: RED,BLUE  4P: RED,GREEN,BLUE,YELLOW)
   Snakes: seat 0 = RED, seat 1 = BLUE */
static int PlayerOfSeat(const Game *g, int seat)
{
    if (seat < 0)
        return -1;

    if (g->state == STATE_SNAKES)
        return seat < 2 ? seat : -1;

    return seat < g->numPlayers ? g->order[seat] : -1;
}

static int SeatOfPlayer(const Game *g, int pid)
{
    if (g->state == STATE_SNAKES)
        return pid;

    for (int i = 0; i < g->numPlayers; i++)
        if (g->order[i] == pid)
            return i;

    return -1;
}

/* Offline: everybody on this computer may act.
   Online: only the player sitting in MY seat may act. */
static bool LocalCanAct(const Game *g, int pid)
{
    if (gNet.role == NET_OFF)
        return true;

    return SeatOfPlayer(g, pid) == gNet.seat;
}

static bool NetIsMe(const Game *g, int pid)
{
    return gNet.role != NET_OFF &&
           gNet.phase == NP_PLAYING &&
           SeatOfPlayer(g, pid) == gNet.seat;
}

/* Used by the lobby screen (the game is not running yet). */
static int SeatToPlayerId(int kind, int count, int seat)
{
    static const int ORDER_4[4] =
        { PLAYER_RED, PLAYER_GREEN, PLAYER_BLUE, PLAYER_YELLOW };

    if (kind == KIND_SNAKES || count != 4)
        return seat == 0 ? PLAYER_RED : PLAYER_BLUE;

    return ORDER_4[seat & 3];
}

/* ================================================================
   SOUND (generated in code, no files needed)
   ================================================================ */

#define SFX_RATE 44100

static Sound gSfx[SFX_COUNT];
static bool gSfxReady = false;
static bool gMuted = false;

static Sound SoundFromBuffer(short *buf, int frames)
{
    Wave w;
    memset(&w, 0, sizeof(w));
    w.frameCount = (unsigned int)frames;
    w.sampleRate = SFX_RATE;
    w.sampleSize = 16;
    w.channels = 1;
    w.data = buf;

    return LoadSoundFromWave(w);
}

/* ---- Soft, pleasant sounds: bells, wood taps and gentle glides
        with a little echo, all generated in code. ---- */

static float *NewMix(float seconds, int *frames)
{
    int n = (int)(seconds * (float)SFX_RATE);
    *frames = n;
    return (float *)calloc((size_t)n, sizeof(float));
}

static float Rand01(void)
{
    return (float)GetRandomValue(0, 10000) / 10000.0f;
}

/* Warm bell / marimba note. */
static void AddBell(
    float *mix, int n, float at,
    float freq, float dur, float vol, float bright)
{
    int start = (int)(at * (float)SFX_RATE);
    int len = (int)(dur * (float)SFX_RATE);
    float decay = 7.0f / dur;

    for (int i = 0; i < len && start + i < n; i++) {
        float t = (float)i / (float)SFX_RATE;
        float env = expf(-t * decay);
        float att = (float)i / (0.004f * (float)SFX_RATE);
        if (att > 1.0f) att = 1.0f;

        float w = 2.0f * PI * freq * t;

        float v = sinf(w)
            + bright * 0.40f * sinf(2.0f * w) * expf(-t * decay * 0.8f)
            + bright * 0.18f * sinf(3.0f * w) * expf(-t * decay * 1.4f)
            + bright * 0.10f * sinf(4.2f * w) * expf(-t * decay * 2.2f);

        mix[start + i] += v * env * att * vol;
    }
}

/* Short, soft wooden tap. */
static void AddWood(
    float *mix, int n, float at, float freq, float vol)
{
    int start = (int)(at * (float)SFX_RATE);
    int len = (int)(0.09f * (float)SFX_RATE);

    for (int i = 0; i < len && start + i < n; i++) {
        float t = (float)i / (float)SFX_RATE;
        float env = expf(-t * 70.0f);
        float att = (float)i / (0.002f * (float)SFX_RATE);
        if (att > 1.0f) att = 1.0f;

        float body = sinf(2.0f * PI * freq * t) * env;
        float click = (Rand01() * 2.0f - 1.0f) * expf(-t * 260.0f) * 0.22f;

        mix[start + i] += (body + click) * att * vol;
    }
}

/* Smooth pitch slide (with optional gentle vibrato). */
static void AddGlide(
    float *mix, int n, float at,
    float f0, float f1, float dur, float vol,
    float vibHz, float vibAmt)
{
    int start = (int)(at * (float)SFX_RATE);
    int len = (int)(dur * (float)SFX_RATE);
    float phase = 0.0f;

    for (int i = 0; i < len && start + i < n; i++) {
        float p = (float)i / (float)len;
        float t = (float)i / (float)SFX_RATE;

        float f = f0 + (f1 - f0) * p;
        f *= 1.0f + vibAmt * sinf(2.0f * PI * vibHz * t);

        phase += 2.0f * PI * f / (float)SFX_RATE;

        float env = (p < 0.06f) ? (p / 0.06f) : (1.0f - p);
        float v = sinf(phase) + 0.20f * sinf(2.0f * phase);

        mix[start + i] += v * env * vol;
    }
}

static void AddEcho(float *mix, int n, float delay, float gain)
{
    int d = (int)(delay * (float)SFX_RATE);

    for (int i = d; i < n; i++)
        mix[i] += mix[i - d] * gain;
}

/* Normalizes to a comfortable level, fades the tail, and builds the Sound. */
static Sound FinishMix(float *mix, int n, float peakTarget)
{
    float peak = 0.0001f;

    for (int i = 0; i < n; i++)
        if (fabsf(mix[i]) > peak)
            peak = fabsf(mix[i]);

    float scale = peakTarget / peak;
    int fade = (int)(0.03f * (float)SFX_RATE);

    short *buf = (short *)malloc((size_t)n * sizeof(short));

    for (int i = 0; i < n; i++) {
        float v = mix[i] * scale;

        if (i > n - fade)
            v *= (float)(n - i) / (float)fade;

        buf[i] = (short)(v * 32000.0f);
    }

    Sound snd = SoundFromBuffer(buf, n);

    free(buf);
    free(mix);

    return snd;
}

static Sound MakeClick(void)
{
    int n;
    float *m = NewMix(0.25f, &n);

    AddBell(m, n, 0.0f, 1319.5f, 0.20f, 1.0f, 0.5f);

    return FinishMix(m, n, 0.30f);
}

static Sound MakeDice(void)
{
    static const float times[10] = {
        0.00f, 0.055f, 0.105f, 0.150f, 0.190f,
        0.225f, 0.255f, 0.283f, 0.308f, 0.330f
    };

    int n;
    float *m = NewMix(0.55f, &n);

    for (int k = 0; k < 10; k++) {
        float freq = 480.0f + Rand01() * 420.0f;
        AddWood(m, n, times[k], freq, 1.0f - (float)k * 0.07f);
    }

    AddWood(m, n, 0.36f, 300.0f, 0.9f);

    return FinishMix(m, n, 0.55f);
}

static Sound MakeStep(void)
{
    int n;
    float *m = NewMix(0.20f, &n);

    AddBell(m, n, 0.0f, 392.0f, 0.16f, 1.0f, 0.25f);
    AddWood(m, n, 0.0f, 210.0f, 0.5f);

    return FinishMix(m, n, 0.40f);
}

static Sound MakeCapture(void)
{
    int n;
    float *m = NewMix(0.70f, &n);

    AddGlide(m, n, 0.0f, 560.0f, 170.0f, 0.32f, 1.0f, 0.0f, 0.0f);
    AddWood(m, n, 0.30f, 130.0f, 0.9f);
    AddEcho(m, n, 0.09f, 0.25f);

    return FinishMix(m, n, 0.60f);
}

static Sound MakeHome(void)
{
    static const float notes[4] = {523.25f, 659.25f, 783.99f, 1046.5f};

    int n;
    float *m = NewMix(1.10f, &n);

    for (int k = 0; k < 4; k++)
        AddBell(m, n, (float)k * 0.09f, notes[k], 0.60f, 1.0f, 0.8f);

    AddEcho(m, n, 0.12f, 0.30f);

    return FinishMix(m, n, 0.55f);
}

static Sound MakeWin(void)
{
    static const float melody[6] =
        {523.25f, 659.25f, 783.99f, 1046.5f, 783.99f, 1046.5f};
    static const float times[6] =
        {0.00f, 0.13f, 0.26f, 0.39f, 0.62f, 0.75f};
    static const float chord[3] = {1046.5f, 1318.5f, 1568.0f};

    int n;
    float *m = NewMix(2.60f, &n);

    for (int k = 0; k < 6; k++)
        AddBell(m, n, times[k], melody[k], 0.70f, 1.0f, 0.8f);

    for (int k = 0; k < 3; k++)
        AddBell(m, n, 0.95f, chord[k], 1.40f, 0.8f, 0.7f);

    AddEcho(m, n, 0.14f, 0.30f);

    return FinishMix(m, n, 0.65f);
}

static Sound MakeSnake(void)
{
    int n;
    float *m = NewMix(1.10f, &n);

    AddGlide(m, n, 0.0f, 640.0f, 120.0f, 0.75f, 1.0f, 6.5f, 0.035f);
    AddWood(m, n, 0.72f, 110.0f, 0.5f);
    AddEcho(m, n, 0.10f, 0.20f);

    return FinishMix(m, n, 0.50f);
}

static Sound MakeLadder(void)
{
    static const float notes[8] = {
        523.25f, 587.33f, 659.25f, 783.99f,
        880.00f, 1046.5f, 1174.7f, 1318.5f
    };

    int n;
    float *m = NewMix(1.00f, &n);

    for (int k = 0; k < 8; k++)
        AddBell(m, n, (float)k * 0.055f, notes[k], 0.40f, 1.0f, 1.0f);

    AddEcho(m, n, 0.10f, 0.30f);

    return FinishMix(m, n, 0.50f);
}

