static unsigned char *DecodeBase64(const char *src, int *outLen)
{
    static signed char table[256];
    static bool ready = false;

    if (!ready) {
        const char *abc =
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

        memset(table, -1, sizeof(table));

        for (int i = 0; i < 64; i++)
            table[(unsigned char)abc[i]] = (signed char)i;

        ready = true;
    }

    size_t n = strlen(src);
    unsigned char *out = (unsigned char *)malloc(n / 4 * 3 + 4);
    int len = 0;
    unsigned int acc = 0;
    int bits = 0;

    if (!out)
        return NULL;

    for (size_t i = 0; i < n; i++) {
        signed char v = table[(unsigned char)src[i]];

        if (v < 0)
            continue;

        acc = (acc << 6) | (unsigned int)v;
        bits += 6;

        if (bits >= 8) {
            bits -= 8;
            out[len++] = (unsigned char)((acc >> bits) & 0xFF);
        }
    }

    *outLen = len;
    return out;
}

/* Replaces *slot with the embedded MP3 (if it can be decoded). */
static void UseEmbeddedMp3(Sound *slot, const char *b64, float volume)
{
    int len = 0;
    unsigned char *data = DecodeBase64(b64, &len);

    if (!data)
        return;

    Wave w = LoadWaveFromMemory(".mp3", data, len);
    free(data);

    if (w.data == NULL)
        return;

    Sound snd = LoadSoundFromWave(w);
    UnloadWave(w);

    SetSoundVolume(snd, volume);

    UnloadSound(*slot);
    *slot = snd;
}

static void InitSounds(void)
{
    InitAudioDevice();

    if (!IsAudioDeviceReady())
        return;

    gSfx[SFX_CLICK]   = MakeClick();
    gSfx[SFX_DICE]    = MakeDice();
    gSfx[SFX_STEP]    = MakeStep();
    gSfx[SFX_CAPTURE] = MakeCapture();
    gSfx[SFX_HOME]    = MakeHome();
    gSfx[SFX_WIN]     = MakeWin();
    gSfx[SFX_SNAKE]   = MakeSnake();
    gSfx[SFX_LADDER]  = MakeLadder();
    gSfx[SFX_START]   = MakeHome();      /* fallback only */

    UseEmbeddedMp3(&gSfx[SFX_DICE],    SND_DICE_B64,  0.85f);
    UseEmbeddedMp3(&gSfx[SFX_START],   SND_START_B64, 0.85f);
    UseEmbeddedMp3(&gSfx[SFX_CAPTURE], SND_OVER_B64,  0.80f);
    UseEmbeddedMp3(&gSfx[SFX_SNAKE],   SND_OVER_B64,  0.80f);

    gSfxReady = true;
}

static void FreeSounds(void)
{
    if (gSfxReady) {
        for (int i = 0; i < SFX_COUNT; i++)
            UnloadSound(gSfx[i]);
    }

    CloseAudioDevice();
}

/* Plays a sound on THIS computer only. */
static void PlaySfxLocal(SfxId id)
{
    if (gSfxReady && !gMuted)
        PlaySound(gSfx[id]);
}

/* Plays a game sound. When hosting, the sound is also queued so the
   joined players hear it too (button clicks are not forwarded). */
static void PlaySfx(SfxId id)
{
    PlaySfxLocal(id);

    if (gNet.role == NET_HOST && id != SFX_CLICK) {
        /* The wire format has 8 bits. SFX_CLICK is never forwarded, so
           its bit (0) carries SFX_START instead. */
        int bit = (id == SFX_START) ? 0 : (int)id;

        for (int i = 0; i < NET_MAX_CLIENTS; i++)
            gSfxOut[i] |= (unsigned char)(1u << bit);
    }
}

/* ================================================================
   BOARD GEOMETRY (LUDO)
   ================================================================ */

static const int RING_CELLS[RING_SIZE][2] = {
    {1,6},{2,6},{3,6},{4,6},{5,6},
    {6,5},{6,4},{6,3},{6,2},{6,1},{6,0},
    {7,0},{8,0},
    {8,1},{8,2},{8,3},{8,4},{8,5},
    {9,6},{10,6},{11,6},{12,6},{13,6},{14,6},
    {14,7},{14,8},
    {13,8},{12,8},{11,8},{10,8},{9,8},
    {8,9},{8,10},{8,11},{8,12},{8,13},{8,14},
    {7,14},{6,14},
    {6,13},{6,12},{6,11},{6,10},{6,9},
    {5,8},{4,8},{3,8},{2,8},{1,8},{0,8},
    {0,7},{0,6}
};

static const int SAFE_RING_INDEX[8] =
    {0, 8, 13, 21, 26, 34, 39, 47};

static const float YARD_SLOT[4][2] = {
    {2,2}, {4,2}, {2,4}, {4,4}
};

static bool IsSafeRingIndex(int ringIndex)
{
    for (int i = 0; i < 8; i++)
        if (SAFE_RING_INDEX[i] == ringIndex) return true;

    return false;
}

static int GetRingIndex(const Player *player, int pos)
{
    if (pos < 0 || pos > LAST_RING_POS) return -1;
    return (player->startIndex + pos) % RING_SIZE;
}

/* Top-left grid corner of a player's yard. */
static Vector2 GetYardOrigin(int playerId)
{
    switch (playerId) {
        case PLAYER_RED:    return (Vector2){0.0f, 0.0f};
        case PLAYER_GREEN:  return (Vector2){9.0f, 0.0f};
        case PLAYER_BLUE:   return (Vector2){9.0f, 9.0f};
        case PLAYER_YELLOW: return (Vector2){0.0f, 9.0f};
        default:            return (Vector2){0.0f, 0.0f};
    }
}

static Vector2 GridToScreen(const Layout *L, float gx, float gy)
{
    return (Vector2) {
        L->boardOrigin.x + gx * L->cell,
        L->boardOrigin.y + gy * L->cell
    };
}

static Rectangle CellRect(const Layout *L, int col, int row)
{
    Vector2 p = GridToScreen(L, (float)col, (float)row);
    return (Rectangle){p.x, p.y, L->cell, L->cell};
}

static Vector2 GetTokenGridPos(const Game *game, int playerId, int tokenIndex)
{
    const Player *player = &game->players[playerId];
    int pos = player->tokens[tokenIndex].pos;

    if (pos == POS_BASE) {
        Vector2 yard = GetYardOrigin(playerId);
        return (Vector2) {
            yard.x + YARD_SLOT[tokenIndex][0],
            yard.y + YARD_SLOT[tokenIndex][1]
        };
    }

    if (pos == POS_FINISHED) {
        float x = 6.7f + 0.28f * (float)(tokenIndex % 2);
        float y = 7.0f + 0.75f * (float)(tokenIndex / 2);

        if (playerId == PLAYER_BLUE)
            return (Vector2){15.0f - x, y};

        if (playerId == PLAYER_GREEN)
            return (Vector2){15.0f - y, x};

        if (playerId == PLAYER_YELLOW)
            return (Vector2){y, 15.0f - x};

        return (Vector2){x, y};
    }

    if (pos <= LAST_RING_POS) {
        int ring = GetRingIndex(player, pos);
        int col = RING_CELLS[ring][0];
        int row = RING_CELLS[ring][1];
        return (Vector2){col + 0.5f, row + 0.5f};
    }

    /* Home lane */
    int step = pos - LANE_START_POS;

    if (playerId == PLAYER_RED)
        return (Vector2){1.5f + step, 7.5f};

    if (playerId == PLAYER_GREEN)
        return (Vector2){7.5f, 1.5f + step};

    if (playerId == PLAYER_YELLOW)
        return (Vector2){7.5f, 13.5f - step};

    return (Vector2){13.5f - step, 7.5f};
}

static void GetTokenScreenInfo(
    const Game *game,
    int playerId,
    int tokenIndex,
    Vector2 *center,
    float *radius)
{
    Vector2 me = GetTokenGridPos(game, playerId, tokenIndex);

    int total = 0;
    int order = 0;

    for (int i = 0; i < game->numPlayers; i++) {
        int p = game->order[i];

        for (int t = 0; t < TOKENS_PER_PLAYER; t++) {
            Vector2 other = GetTokenGridPos(game, p, t);

            if (fabsf(other.x - me.x) < 0.01f &&
                fabsf(other.y - me.y) < 0.01f) {

                if (p == playerId && t == tokenIndex)
                    order = total;

                total++;
            }
        }
    }

    float r = 0.31f;
    float offsetX = 0.0f;

    if (game->players[playerId].tokens[tokenIndex].pos == POS_FINISHED) {
        r = 0.17f;
    } else if (total > 1) {
        r = 0.25f;
        offsetX =
            ((float)order - (float)(total - 1) / 2.0f) * 0.27f;
    }

    center->x =
        game->layout.boardOrigin.x +
        (me.x + offsetX) * game->layout.cell;

    center->y =
        game->layout.boardOrigin.y +
        me.y * game->layout.cell;

    *radius = r * game->layout.cell;
}

/* ================================================================
   LAYOUT
   ================================================================ */

static Layout ComputeLayout(int sw, int sh, int numPlayers)
{
    Layout L;
    memset(&L, 0, sizeof(L));

    /* Compact mobile-Ludo layout:
       small score cards -> generous vertical spacing -> board,
       with MENU / RESTART in a dedicated right sidebar. */
    const float sideMargin = 22.0f;
    const float topCardH = 68.0f;
    const float bottomCardH = 68.0f;
    const float verticalGap = 22.0f;
    const float sidebarW = 116.0f;
    const float sidebarGap = 18.0f;

    float contentW = (float)sw - sidebarW - sidebarGap - 2.0f * sideMargin;
    float boardMax = fminf(
        contentW,
        (float)sh - topCardH - bottomCardH - verticalGap * 3.0f);

    if (boardMax < 430.0f)
        boardMax = 430.0f;

    L.boardSize = boardMax;
    L.cell = boardMax / (float)GRID_SIZE;

    float contentX = sideMargin;
    float boardAreaW = contentW;

    L.boardOrigin = (Vector2) {
        contentX + (boardAreaW - boardMax) * 0.5f,
        topCardH + verticalGap
    };

    float bottomY = L.boardOrigin.y + boardMax + verticalGap;

    if (numPlayers == 4) {
        /* 4 players: two cards above and two cards below the board,
           placed next to their own yards.
           Top:    RED (left)    GREEN (right)
           Bottom: YELLOW (left) BLUE  (right) */
        const float cardGap = 16.0f;
        float cardW = (contentW - cardGap) * 0.5f;
        float leftX = contentX;
        float rightX = contentX + cardW + cardGap;

        L.playerCard[PLAYER_RED] =
            (Rectangle){ leftX,  12.0f,  cardW, topCardH };
        L.playerCard[PLAYER_GREEN] =
            (Rectangle){ rightX, 12.0f,  cardW, topCardH };
        L.playerCard[PLAYER_YELLOW] =
            (Rectangle){ leftX,  bottomY, cardW, bottomCardH };
        L.playerCard[PLAYER_BLUE] =
            (Rectangle){ rightX, bottomY, cardW, bottomCardH };
    } else {
        float cardWidth = boardMax;
        float cardX = L.boardOrigin.x;

        L.playerCard[PLAYER_RED] = (Rectangle) {
            cardX, 12.0f, cardWidth, topCardH
        };

        L.playerCard[PLAYER_BLUE] = (Rectangle) {
            cardX,
            bottomY,
            cardWidth,
            bottomCardH
        };
    }

    float diceSize = 54.0f;

    for (int p = 0; p < MAX_PLAYERS; p++) {
        Rectangle card = L.playerCard[p];

        L.diceBox[p] = (Rectangle) {
            card.x + card.width - diceSize - 12.0f,
            card.y + (card.height - diceSize) * 0.5f,
            diceSize,
            diceSize
        };
    }

    /* The active player's roll button is assigned every frame in
       UpdateGame(), so it follows the active player's dice. */
    L.rollButton = (Rectangle) {0, 0, 0, 0};

    /* Dedicated compact sidebar for MENU and RESTART. */
    float sidebarX = L.boardOrigin.x + boardMax + sidebarGap;
    float sidebarH = 126.0f;
    float sidebarY = L.boardOrigin.y + (boardMax - sidebarH) * 0.5f;

    L.sideBar = (Rectangle) {
        sidebarX, sidebarY, sidebarW, sidebarH
    };

    L.menuButton = (Rectangle) {
        sidebarX + 10.0f,
        sidebarY + 12.0f,
        sidebarW - 20.0f,
        42.0f
    };

    L.restartButton = (Rectangle) {
        sidebarX + 10.0f,
        sidebarY + 66.0f,
        sidebarW - 20.0f,
        42.0f
    };

    float ms = fminf(
        (float)sw / 1000.0f,
        (float)sh / 720.0f);

    float cx = (float)sw * 0.5f;
    float cy = (float)sh * 0.5f;

    for (int i = 0; i < 6; i++) {
        L.menuBtn[i] =
            (Rectangle){cx - 150.0f * ms,
                        cy - 40.0f * ms + (float)i * 66.0f * ms,
                        300.0f * ms, 54.0f * ms};
    }

    L.winBox =
        (Rectangle){cx - 265.0f * ms, cy - 190.0f * ms,
                    530.0f * ms, 380.0f * ms};

    L.winRestartButton =
        (Rectangle){L.winBox.x + 30.0f * ms,
                    L.winBox.y + 286.0f * ms,
                    225.0f * ms, 54.0f * ms};

    L.winMenuButton =
        (Rectangle){L.winBox.x + 275.0f * ms,
                    L.winBox.y + 286.0f * ms,
                    225.0f * ms, 54.0f * ms};

    return L;
}

/* ================================================================
   LUDO GAME LOGIC
   ================================================================ */

static int CountFinished(
    const Game *game,
    int player)
{
    int count = 0;

    for (int t = 0; t < TOKENS_PER_PLAYER; t++)
        if (game->players[player].tokens[t].pos
            == POS_FINISHED)
            count++;

    return count;
}

static int CountHome(
    const Game *game,
    int player)
{
    int count = 0;

    for (int t = 0; t < TOKENS_PER_PLAYER; t++)
        if (game->players[player].tokens[t].pos
            == POS_BASE)
            count++;

    return count;
}

/* Team mode partners sit in opposite corners:
   RED + BLUE  vs  GREEN + YELLOW. */
static int TeammateOf(int p)
{
    switch (p) {
        case PLAYER_RED:   return PLAYER_BLUE;
        case PLAYER_BLUE:  return PLAYER_RED;
        case PLAYER_GREEN: return PLAYER_YELLOW;
        default:           return PLAYER_GREEN;
    }
}

static bool SameTeam(const Game *game, int a, int b)
{
    if (a == b)
        return true;

    return game->teamMode && TeammateOf(a) == b;
}

/* Whose tokens are moved with the current roll.
   In team mode, a player who already finished all tokens
   moves the teammate's tokens instead. */
static int ControlledPlayer(const Game *game)
{
    int cur = game->currentPlayer;

    if (game->teamMode &&
        CountFinished(game, cur) == TOKENS_PER_PLAYER) {

        int mate = TeammateOf(cur);

        if (CountFinished(game, mate) < TOKENS_PER_PLAYER)
            return mate;
    }

    return cur;
}

/* Sets 2 or 4 player mode: turn order and player labels. */
static void SetPlayerCount(Game *game, int count)
{
    static const int ORDER_2[2] = { PLAYER_RED, PLAYER_BLUE };
    static const int ORDER_4[4] =
        { PLAYER_RED, PLAYER_GREEN, PLAYER_BLUE, PLAYER_YELLOW };
    static const char *LABELS[4] =
        { "Player 1", "Player 2", "Player 3", "Player 4" };

    if (count != 4)
        count = 2;

    game->numPlayers = count;

    const int *order = (count == 4) ? ORDER_4 : ORDER_2;

    for (int i = 0; i < count; i++) {
        int id = order[i];

        game->order[i] = id;

        if (game->isBot[id])
            game->players[id].subtitle = "Computer";
        else if (game->teamMode)
            game->players[id].subtitle =
                (id == PLAYER_RED || id == PLAYER_BLUE)
                    ? "Team A" : "Team B";
        else
            game->players[id].subtitle = LABELS[i];
    }
}

static int NextPlayer(const Game *game, int current)
{
    for (int i = 0; i < game->numPlayers; i++) {
        if (game->order[i] == current)
            return game->order[(i + 1) % game->numPlayers];
    }

    return game->order[0];
}

static void ResetGame(Game *game)
{
    for (int p = 0; p < MAX_PLAYERS; p++)
        for (int t = 0; t < TOKENS_PER_PLAYER; t++)
            game->players[p].tokens[t].pos = POS_BASE;

    game->currentPlayer = game->order[0];
    game->mover = game->currentPlayer;
    game->diceValue = 0;
    game->shownDice = 0;

    for (int p = 0; p < MAX_PLAYERS; p++)
        game->playerDice[p] = 0;

    memset(game->legal, 0, sizeof(game->legal));

    game->legalCount = 0;
    game->movingToken = -1;
    game->stepsLeft = 0;

    game->timer = 0.0f;
    game->faceTimer = 0.0f;
    game->animationTime = 0.0f;

    game->winner = -1;

    game->state = STATE_WAIT_ROLL;

    snprintf(game->message, MSG_LEN,
             "Roll the dice to start your turn.");
}

/* Starts a Ludo game.
   count     : 2 or 4 players
   teams     : team mode (only with 4 players)
   vsComputer: BLUE is played by the computer (only with 2 players) */
static void StartLudo(
    Game *game, int count, bool teams, bool vsComputer)
{
    game->teamMode = teams && count == 4;

    for (int p = 0; p < MAX_PLAYERS; p++)
        game->isBot[p] = false;

    if (vsComputer && count != 4)
        game->isBot[PLAYER_BLUE] = true;

    SetPlayerCount(game, count);
    ResetGame(game);

    PlaySfx(SFX_START);
}

static void StartGame(Game *game, int playerCount)
{
    StartLudo(game, playerCount, false, false);
}

static int GetLegalMoves(
    const Game *game,
    int player,
    int dice,
    bool legal[TOKENS_PER_PLAYER])
{
    int count = 0;

    for (int t = 0; t < TOKENS_PER_PLAYER; t++) {
        int pos = game->players[player].tokens[t].pos;
        bool ok = false;

        if (pos == POS_BASE)
            ok = (dice == 6);
        else if (pos < POS_FINISHED)
            ok = (pos + dice <= POS_FINISHED);

        legal[t] = ok;

        if (ok)
            count++;
    }

    return count;
}

static int CheckCapture(Game *game, int player, int tokenIndex)
{
    Player *me = &game->players[player];

    int ringIndex =
        GetRingIndex(me, me->tokens[tokenIndex].pos);

    if (ringIndex < 0)
        return 0;

    if (IsSafeRingIndex(ringIndex))
        return 0;

    int captured = 0;

    for (int i = 0; i < game->numPlayers; i++) {
        int opId = game->order[i];

        /* Never capture yourself or (in team mode) your teammate. */
        if (SameTeam(game, player, opId))
            continue;

        Player *opponent = &game->players[opId];

        for (int t = 0; t < TOKENS_PER_PLAYER; t++) {
            if (GetRingIndex(opponent, opponent->tokens[t].pos)
                == ringIndex) {

                opponent->tokens[t].pos = POS_BASE;
                captured++;
            }
        }
    }

    return captured;
}

static bool CheckWinner(const Game *game, int player)
{
    for (int t = 0; t < TOKENS_PER_PLAYER; t++) {
        if (game->players[player].tokens[t].pos != POS_FINISHED)
            return false;
    }

    if (game->teamMode) {
        int mate = TeammateOf(player);

        for (int t = 0; t < TOKENS_PER_PLAYER; t++) {
            if (game->players[mate].tokens[t].pos != POS_FINISHED)
                return false;
        }
    }

    return true;
}

static void AdvanceTurn(Game *game, const char *note)
{
    bool bonus = (game->diceValue == 6);

    if (!bonus)
        game->currentPlayer = NextPlayer(game, game->currentPlayer);

    game->mover = game->currentPlayer;
    game->state = STATE_WAIT_ROLL;
    game->legalCount = 0;
    game->timer = 0.0f;

    memset(game->legal, 0, sizeof(game->legal));

    if (bonus) {
        snprintf(game->message, MSG_LEN,
                 "%s Rolled a 6! Roll again.",
                 note);
    } else {
        snprintf(game->message, MSG_LEN,
                 "%s %s's turn.",
                 note,
                 game->players[game->currentPlayer].name);
    }
}

static void FinishMove(Game *game)
{
    int player = game->mover;
    int token = game->movingToken;

    char note[100] = "";

    int captured = CheckCapture(game, player, token);

    if (captured > 0) {
        snprintf(note, sizeof(note),
                 "%s captured %d opponent token%s!",
                 game->players[player].name,
                 captured,
                 captured == 1 ? "" : "s");

        PlaySfx(SFX_CAPTURE);
    } else if (game->players[player].tokens[token].pos
               == POS_FINISHED) {

        snprintf(note, sizeof(note),
                 "A %s token reached HOME!",
                 game->players[player].name);

        PlaySfx(SFX_HOME);
    }

    game->movingToken = -1;

    if (CheckWinner(game, player)) {
        game->winner = player;
        game->state = STATE_GAME_OVER;

        snprintf(game->message, MSG_LEN,
                 "%s wins the match!",
                 game->players[player].name);

        PlaySfx(SFX_WIN);

        return;
    }

    AdvanceTurn(game, note);
}

static void StartDiceRoll(Game *game)
{
    game->state = STATE_DICE_ROLLING;
    game->timer = 0.0f;
    game->faceTimer = 0.0f;
    game->mover = game->currentPlayer;

    game->shownDice = GetRandomValue(1, 6);
    game->playerDice[game->currentPlayer] = game->shownDice;

    snprintf(game->message, MSG_LEN, "%s is rolling...",
             game->players[game->currentPlayer].name);

    PlaySfx(SFX_DICE);
}

static void RollDice(Game *game)
{
    const char *name =
        game->players[game->currentPlayer].name;

    game->diceValue = GetRandomValue(1, 6);
    game->shownDice = game->diceValue;
    game->playerDice[game->currentPlayer] = game->diceValue;

    game->mover = ControlledPlayer(game);

    game->legalCount =
        GetLegalMoves(
            game,
            game->mover,
            game->diceValue,
            game->legal);

    game->timer = 0.0f;

    if (game->legalCount == 0) {
        game->state = STATE_NO_MOVES;

        snprintf(game->message, MSG_LEN,
                 "%s rolled %d. No legal move.",
                 name,
                 game->diceValue);
    } else {
        game->state = STATE_CHOOSE_TOKEN;

        if (game->legalCount == 1) {
            snprintf(game->message, MSG_LEN,
                     "%s rolled %d. Moving automatically.",
                     name,
                     game->diceValue);
        } else {
            snprintf(game->message, MSG_LEN,
                     "%s rolled %d. Select a glowing token.",
                     name,
                     game->diceValue);
        }
    }
}

static bool MoveToken(Game *game, int tokenIndex)
{
    if (tokenIndex < 0 ||
        tokenIndex >= TOKENS_PER_PLAYER)
        return false;

    if (!game->legal[tokenIndex])
        return false;

    int pos =
        game->players[game->mover]
        .tokens[tokenIndex].pos;

    game->movingToken = tokenIndex;

    game->stepsLeft =
        (pos == POS_BASE) ? 1 : game->diceValue;

    game->timer = 0.0f;
    game->state = STATE_TOKEN_MOVING;

    snprintf(game->message, MSG_LEN, "Moving token...");

    return true;
}

/* ---------------- Computer player (Ludo) ---------------- */

static float ThreatAt(const Game *game, int mover, int ring)
{
    /* Number of enemy tokens 1..6 squares behind this ring square. */
    int danger = 0;

    for (int i = 0; i < game->numPlayers; i++) {
        int opId = game->order[i];

        if (SameTeam(game, mover, opId))
            continue;

        const Player *op = &game->players[opId];

        for (int t = 0; t < TOKENS_PER_PLAYER; t++) {
            int oring = GetRingIndex(op, op->tokens[t].pos);

            if (oring < 0)
                continue;

            int d = (ring - oring + RING_SIZE) % RING_SIZE;

            if (d >= 1 && d <= 6)
                danger++;
        }
    }

    return (float)danger;
}

static int BotChooseToken(const Game *game)
{
    int mover = game->mover;
    const Player *me = &game->players[mover];

    int best = -1;
    float bestScore = -1.0e9f;

    for (int t = 0; t < TOKENS_PER_PLAYER; t++) {

        if (!game->legal[t])
            continue;

        int pos = me->tokens[t].pos;
        int dest = (pos == POS_BASE) ? 0 : pos + game->diceValue;

        float score = (float)dest * 0.3f;

        if (pos == POS_BASE)
            score += 45.0f;

        if (dest == POS_FINISHED)
            score += 100.0f;
        else if (dest >= LANE_START_POS)
            score += 35.0f;

        int ring = GetRingIndex(me, dest);

        if (ring >= 0) {
            if (IsSafeRingIndex(ring)) {
                score += 30.0f;
            } else {
                int caps = 0;

                for (int i = 0; i < game->numPlayers; i++) {
                    int opId = game->order[i];

                    if (SameTeam(game, mover, opId))
                        continue;

                    const Player *op = &game->players[opId];

                    for (int k = 0; k < TOKENS_PER_PLAYER; k++)
                        if (GetRingIndex(op, op->tokens[k].pos) == ring)
                            caps++;
                }

                score += (float)caps * 80.0f;
                score -= ThreatAt(game, mover, ring) * 12.0f;
            }
        }

        /* Running away from a threatened square is good. */
        int here = GetRingIndex(me, pos);

        if (here >= 0 && !IsSafeRingIndex(here) &&
            ThreatAt(game, mover, here) > 0.0f)
            score += 15.0f;

        score += (float)GetRandomValue(0, 5) * 0.1f;

        if (score > bestScore) {
            bestScore = score;
            best = t;
        }
    }

    return best;
}

/* ================================================================
   SNAKES & LADDERS LOGIC
   ================================================================ */

#define NUM_LADDERS 8
#define NUM_SNAKES  8

static const Link LADDERS[NUM_LADDERS] = {
    {4, 14}, {9, 31}, {20, 38}, {28, 84},
    {40, 59}, {51, 67}, {63, 81}, {71, 91}
};

/* from = snake head (top), to = snake tail (bottom) */
static const Link SNAKES[NUM_SNAKES] = {
    {17, 7}, {54, 34}, {62, 19}, {64, 60},
    {87, 24}, {93, 73}, {95, 75}, {98, 79}
};

static int JumpTarget(int pos)
{
    for (int i = 0; i < NUM_LADDERS; i++)
        if (LADDERS[i].from == pos) return LADDERS[i].to;

    for (int i = 0; i < NUM_SNAKES; i++)
        if (SNAKES[i].from == pos) return SNAKES[i].to;

    return 0;
}

static void SnakeToast(SnakeGame *s, const char *text)
{
    snprintf(s->toast, sizeof(s->toast), "%s", text);
    s->toastTimer = 1.7f;
}

static void StartSnakes(Game *game, bool vsComputer)
{
    SnakeGame *s = &game->snake;

    memset(s, 0, sizeof(*s));

    s->vsComputer = vsComputer;
    s->pos[0] = 0;      /* 0 = not on the board yet (needs a 1 or a 6) */
    s->pos[1] = 0;
    s->current = 0;
    s->winner = -1;
    s->state = SN_WAIT_ROLL;

    game->players[PLAYER_RED].subtitle = "Player 1";
    game->players[PLAYER_BLUE].subtitle =
        vsComputer ? "Computer" : "Player 2";

    game->state = STATE_SNAKES;

    PlaySfx(SFX_START);
}

static void AdvanceSnakeTurn(SnakeGame *s)
{
    /* In Snakes & Ladders only a 1 gives an extra roll
       (a 6 is a normal move). */
    bool bonus = (s->dice == 1);

    if (!bonus)
        s->current = 1 - s->current;

    s->state = SN_WAIT_ROLL;
    s->timer = 0.0f;

    if (bonus)
        SnakeToast(s, "Rolled a 1! Roll again.");
}

static void FinishSnakeMove(SnakeGame *s)
{
    if (s->pos[s->current] >= SNAKE_LAST) {
        s->winner = s->current;
        s->state = SN_OVER;
        PlaySfx(SFX_WIN);
        return;
    }

    AdvanceSnakeTurn(s);
}

static void StartSnakeRoll(SnakeGame *s)
{
    s->state = SN_ROLLING;
    s->timer = 0.0f;
    s->faceTimer = 0.0f;
    s->shown = GetRandomValue(1, 6);
    s->playerDice[s->current] = s->shown;

    PlaySfx(SFX_DICE);
}

/* ================================================================
   NETWORK  (plain TCP sockets - LAN / hotspot, no internet needed)

   The HOST runs the whole game (dice, moves, bots, rules).
   Every ~30 ms it sends a small "snapshot" of the game to each
   joined player, together with the sounds that happened.
   Joined players only send tiny requests: ROLL, PICK token, RESTART.
   ================================================================ */

static void NetSetNotice(const char *text)
{
    snprintf(gNet.notice, sizeof(gNet.notice), "%s", text);
    gNet.noticeTimer = 5.0f;
}

static bool NetSystemInit(void)
{
    if (gNet.wsReady)
        return true;

#if defined(_WIN32)
    WSADATA data;

    if (WSAStartup(MAKEWORD(2, 2), &data) != 0)
        return false;
#endif

    gNet.wsReady = true;
    return true;
}

static void NetShutdownSystem(void)
{
#if defined(_WIN32)
    if (gNet.wsReady)
        WSACleanup();
#endif
    gNet.wsReady = false;
}

static void NetCloseSock(NetSock s)
{
#if defined(_WIN32)
    closesocket(s);
#else
    close(s);
#endif
}

static void NetSetNonBlocking(NetSock s)
{
#if defined(_WIN32)
    u_long mode = 1;
    ioctlsocket(s, FIONBIO, &mode);
#else
    int flags = fcntl(s, F_GETFL, 0);
    fcntl(s, F_SETFL, flags | O_NONBLOCK);
#endif
}

static void NetSetNoDelay(NetSock s)
{
    int one = 1;
    setsockopt(s, IPPROTO_TCP, TCP_NODELAY, (const char *)&one, sizeof(one));
}

/* true when the last socket error only means "nothing yet, try later" */
static bool NetWouldBlock(void)
{
#if defined(_WIN32)
    int e = WSAGetLastError();
    return e == WSAEWOULDBLOCK || e == WSAEINPROGRESS;
#else
    return errno == EWOULDBLOCK || errno == EAGAIN ||
           errno == EINPROGRESS || errno == EINTR;
#endif
}

static void NetConnReset(NetConn *c)
{
    c->sock = NET_INVALID;
    c->used = false;
    c->rxLen = 0;
    c->txLen = 0;
}

static void NetConnOpen(NetConn *c, NetSock s)
{
    NetConnReset(c);
    c->sock = s;
    c->used = true;
}

static void NetConnClose(NetConn *c)
{
    if (c->used && c->sock != NET_INVALID)
        NetCloseSock(c->sock);

    NetConnReset(c);
}

/* Closes everything and leaves network mode. */
static void NetStop(void)
{
    for (int i = 0; i < NET_MAX_CLIENTS; i++)
        NetConnClose(&gNet.conns[i]);

    if (gNet.listenSock != NET_INVALID && gNet.role == NET_HOST &&
        gNet.phase == NP_HOST_WAIT)
        NetCloseSock(gNet.listenSock);

    gNet.listenSock = NET_INVALID;
    gNet.role = NET_OFF;
    gNet.phase = NP_NONE;
    gNet.seat = 0;
    gNet.sendTimer = 0.0f;
    gNet.connectTimer = 0.0f;

    memset(gSfxOut, 0, sizeof(gSfxOut));
}

static void ReturnToMenu(Game *game)
{
    NetStop();
    game->state = STATE_MENU;
    game->menuPage = MENU_MAIN;
}

/* ---- message framing: [u16 length][u8 type][payload] ---- */

static bool NetQueue(
    NetConn *c, int type,
    const unsigned char *payload, int len)
{
    int body = 1 + len;

    if (!c->used)
        return false;

    if (c->txLen + 2 + body > NET_TX_SIZE)
        return false;

    c->tx[c->txLen++] = (unsigned char)(body & 0xFF);
    c->tx[c->txLen++] = (unsigned char)((body >> 8) & 0xFF);
    c->tx[c->txLen++] = (unsigned char)type;

    if (len > 0) {
        memcpy(c->tx + c->txLen, payload, (size_t)len);
        c->txLen += len;
    }

    return true;
}

/* returns false when the connection is lost */
static bool NetFlush(NetConn *c)
{
    while (c->used && c->txLen > 0) {
        int n = (int)send(
            c->sock, (const char *)c->tx, c->txLen, NET_SEND_FLAGS);

        if (n > 0) {
            memmove(c->tx, c->tx + n, (size_t)(c->txLen - n));
            c->txLen -= n;
        } else if (n < 0 && NetWouldBlock()) {
            break;
        } else {
            return false;
        }
    }

    return true;
}

/* returns false when the connection is lost */
static bool NetRecv(NetConn *c)
{
    while (c->used) {
        int space = NET_RX_SIZE - c->rxLen;

        if (space <= 0)
            break;

        int n = (int)recv(
            c->sock, (char *)c->rx + c->rxLen, space, 0);

        if (n > 0)
            c->rxLen += n;
        else if (n == 0)
            return false;
        else if (NetWouldBlock())
            break;
        else
            return false;
    }

    return true;
}

/* 1 = got a message, 0 = nothing complete yet, -1 = broken stream */
static int NetNextMsg(
    NetConn *c, int *type, unsigned char *out, int *len)
{
    if (c->rxLen < 3)
        return 0;

    int body = c->rx[0] | (c->rx[1] << 8);

    if (body < 1 || body > NET_MSG_MAX)
        return -1;

    if (c->rxLen < 2 + body)
        return 0;

    *type = c->rx[2];
    *len = body - 1;

    if (*len > 0)
        memcpy(out, c->rx + 3, (size_t)*len);

    int used = 2 + body;

    memmove(c->rx, c->rx + used, (size_t)(c->rxLen - used));
    c->rxLen -= used;

    return 1;
}

/* ---- tiny byte writer / reader ---- */

typedef struct {
    unsigned char *p;
    int len;
    int cap;
} NetW;

typedef struct {
    const unsigned char *p;
    int len;
    int pos;
    bool bad;
} NetR;

static void W8(NetW *w, int v)
{
    if (w->len < w->cap)
        w->p[w->len++] = (unsigned char)(v & 0xFF);
}

static void WF(NetW *w, float f)
{
    unsigned char b[4];

    memcpy(b, &f, 4);

    for (int i = 0; i < 4; i++)
        W8(w, b[i]);
}

static void WStr(NetW *w, const char *s, int maxLen)
{
    int n = (int)strlen(s);

    if (n > maxLen)
        n = maxLen;

    W8(w, n);

    for (int i = 0; i < n; i++)
        W8(w, (unsigned char)s[i]);
}

static int R8(NetR *r)
{
    if (r->pos >= r->len) {
        r->bad = true;
        return 0;
    }

    return r->p[r->pos++];
}

static float RF(NetR *r)
{
    unsigned char b[4];
    float f;

    for (int i = 0; i < 4; i++)
        b[i] = (unsigned char)R8(r);

    memcpy(&f, b, 4);

    return f;
}

static void RStr(NetR *r, char *dst, int dstSize)
{
    int n = R8(r);
    int k = 0;

    for (int i = 0; i < n; i++) {
        int c = R8(r);

        if (k < dstSize - 1)
            dst[k++] = (char)c;
    }

    dst[k] = '\0';
}

/* ---- snapshot (host -> client) ---- */

static int NetBuildSnapshot(
    const Game *g, unsigned char sfx, unsigned char *buf, int cap)
{
    NetW w = { buf, 0, cap };
    bool snakes = (g->state == STATE_SNAKES);

    W8(&w, snakes ? 1 : 0);
    W8(&w, sfx);

    if (!snakes) {
        int bits = 0;

        W8(&w, (int)g->state);
        W8(&w, g->numPlayers);
        W8(&w, g->teamMode ? 1 : 0);
        W8(&w, g->currentPlayer);
        W8(&w, g->mover);
        W8(&w, g->diceValue);
        W8(&w, g->shownDice);

        for (int p = 0; p < MAX_PLAYERS; p++)
            W8(&w, g->playerDice[p]);

        for (int t = 0; t < TOKENS_PER_PLAYER; t++)
            if (g->legal[t])
                bits |= (1 << t);

        W8(&w, bits);
        W8(&w, g->legalCount);
        W8(&w, g->movingToken);
        W8(&w, g->winner);

        for (int p = 0; p < MAX_PLAYERS; p++)
            for (int t = 0; t < TOKENS_PER_PLAYER; t++)
                W8(&w, g->players[p].tokens[t].pos);

        WStr(&w, g->message, MSG_LEN - 1);
    } else {
        const SnakeGame *s = &g->snake;

        W8(&w, (int)s->state);
        W8(&w, s->pos[0]);
        W8(&w, s->pos[1]);
        W8(&w, s->current);
        W8(&w, s->dice);
        W8(&w, s->shown);
        W8(&w, s->playerDice[0]);
        W8(&w, s->playerDice[1]);
        W8(&w, s->stepsLeft);
        W8(&w, s->slideFrom);
        W8(&w, s->slideTo);
        WF(&w, s->slideT);
        W8(&w, s->winner);
        WStr(&w, s->toast, 63);
        WF(&w, s->toastTimer);
    }

    return w.len;
}

/* returns false when the snapshot is damaged (it is then ignored) */
static bool NetApplySnapshot(Game *g, const unsigned char *data, int len)
{
    NetR r = { data, len, 0, false };

    int snakes = R8(&r);
    int sfx = R8(&r);

    if (snakes) {
        SnakeGame t = g->snake;
        int st = R8(&r);

        t.pos[0] = R8(&r);
        t.pos[1] = R8(&r);
        t.current = R8(&r);
        t.dice = R8(&r);
        t.shown = R8(&r);
        t.playerDice[0] = R8(&r);
        t.playerDice[1] = R8(&r);
        t.stepsLeft = R8(&r);
        t.slideFrom = R8(&r);
        t.slideTo = R8(&r);
        t.slideT = RF(&r);
        t.winner = (signed char)R8(&r);
        RStr(&r, t.toast, (int)sizeof(t.toast));
        t.toastTimer = RF(&r);

        if (r.bad || st < 0 || st > (int)SN_OVER ||
            t.current < 0 || t.current > 1 ||
            t.pos[0] > SNAKE_LAST || t.pos[1] > SNAKE_LAST ||
            t.slideFrom > SNAKE_LAST || t.slideTo > SNAKE_LAST ||
            t.winner < -1 || t.winner > 1)
            return false;

        t.state = (SnakeState)st;
        t.vsComputer = false;

        g->snake = t;
        g->players[PLAYER_RED].subtitle = "Player 1";
        g->players[PLAYER_BLUE].subtitle = "Player 2";
        g->state = STATE_SNAKES;
    } else {
        int st = R8(&r);
        int np = R8(&r);
        int team = R8(&r);
        int cur = R8(&r);
        int mover = R8(&r);
        int dv = R8(&r);
        int sd = R8(&r);
        int pd[MAX_PLAYERS];
        int bits, lc, mt, win;
        int pos[MAX_PLAYERS * TOKENS_PER_PLAYER];
        char msg[MSG_LEN];

        for (int p = 0; p < MAX_PLAYERS; p++)
            pd[p] = R8(&r);

        bits = R8(&r);
        lc = R8(&r);
        mt = (signed char)R8(&r);
        win = (signed char)R8(&r);

        for (int i = 0; i < MAX_PLAYERS * TOKENS_PER_PLAYER; i++)
            pos[i] = (signed char)R8(&r);

        RStr(&r, msg, (int)sizeof(msg));

        if (r.bad ||
            st < (int)STATE_WAIT_ROLL || st > (int)STATE_GAME_OVER ||
            (np != 2 && np != 4) ||
            cur < 0 || cur >= MAX_PLAYERS ||
            mover < 0 || mover >= MAX_PLAYERS ||
            lc > TOKENS_PER_PLAYER ||
            mt < -1 || mt >= TOKENS_PER_PLAYER ||
            win < -1 || win >= MAX_PLAYERS)
            return false;

        for (int i = 0; i < MAX_PLAYERS * TOKENS_PER_PLAYER; i++)
            if (pos[i] < POS_BASE || pos[i] > POS_FINISHED)
                return false;

        bool setup =
            g->numPlayers != np ||
            g->teamMode != (team != 0) ||
            g->state == STATE_SNAKES ||
            g->state == STATE_NET_LOBBY ||
            g->state == STATE_MENU;

        if (setup) {
            g->teamMode = (team != 0);

            for (int p = 0; p < MAX_PLAYERS; p++)
                g->isBot[p] = false;

            SetPlayerCount(g, np);
        }

        g->state = (GameState)st;
        g->currentPlayer = cur;
        g->mover = mover;
        g->diceValue = dv;
        g->shownDice = sd;

        for (int p = 0; p < MAX_PLAYERS; p++)
            g->playerDice[p] = pd[p];

        for (int t = 0; t < TOKENS_PER_PLAYER; t++)
            g->legal[t] = ((bits >> t) & 1) != 0;

        g->legalCount = lc;
        g->movingToken = mt;
        g->winner = win;

        for (int p = 0; p < MAX_PLAYERS; p++)
            for (int t = 0; t < TOKENS_PER_PLAYER; t++)
                g->players[p].tokens[t].pos =
                    pos[p * TOKENS_PER_PLAYER + t];

        snprintf(g->message, MSG_LEN, "%s", msg);
    }

    for (int i = 0; i < 8; i++)
        if (sfx & (1 << i))
            PlaySfxLocal(i == 0 ? SFX_START : (SfxId)i);

    return true;
}

/* ---- finding this computer's IP address (shown on the host screen) ---- */

static void NetAddIp(const char *ip)
{
    if (ip[0] == '\0' || strcmp(ip, "0.0.0.0") == 0 ||
        strncmp(ip, "127.", 4) == 0 || strncmp(ip, "169.254.", 8) == 0)
        return;

    for (int i = 0; i < gNet.localIpCount; i++)
        if (strcmp(gNet.localIps[i], ip) == 0)
            return;

    if (gNet.localIpCount < NET_MAX_IPS) {
        snprintf(gNet.localIps[gNet.localIpCount],
                 sizeof(gNet.localIps[0]), "%s", ip);
        gNet.localIpCount++;
    }
}

static void NetDetectIPs(void)
{
    char text[64];

    gNet.localIpCount = 0;

    /* 1) The address the OS would use to leave this computer.
          (A UDP "connect" sends nothing - it only picks a route.) */
    NetSock s = socket(AF_INET, SOCK_DGRAM, 0);

    if (s != NET_INVALID) {
        struct sockaddr_in a;

        memset(&a, 0, sizeof(a));
        a.sin_family = AF_INET;
        a.sin_port = htons(53);
        inet_pton(AF_INET, "8.8.8.8", &a.sin_addr);

        if (connect(s, (struct sockaddr *)&a, sizeof(a)) == 0) {
            struct sockaddr_in me;
            NetLen ml = (NetLen)sizeof(me);

            memset(&me, 0, sizeof(me));

            if (getsockname(s, (struct sockaddr *)&me, &ml) == 0) {
                inet_ntop(AF_INET, &me.sin_addr, text, sizeof(text));
                NetAddIp(text);
            }
        }

        NetCloseSock(s);
    }

    /* 2) Every IPv4 address of every network adapter. */
#if defined(_WIN32)
    {
        char host[256];

        if (gethostname(host, sizeof(host)) == 0) {
            struct hostent *he = gethostbyname(host);

            if (he && he->h_addrtype == AF_INET) {
                for (int i = 0; he->h_addr_list[i]; i++) {
                    struct in_addr ia;

                    memcpy(&ia, he->h_addr_list[i], sizeof(ia));
                    inet_ntop(AF_INET, &ia, text, sizeof(text));
                    NetAddIp(text);
                }
            }
        }
    }
#else
    {
        struct ifaddrs *list = NULL;

        if (getifaddrs(&list) == 0) {
            for (struct ifaddrs *it = list; it; it = it->ifa_next) {
                if (!it->ifa_addr || it->ifa_addr->sa_family != AF_INET)
                    continue;

                if (!(it->ifa_flags & IFF_UP))
                    continue;

                struct sockaddr_in *sin = (struct sockaddr_in *)it->ifa_addr;

                inet_ntop(AF_INET, &sin->sin_addr, text, sizeof(text));
                NetAddIp(text);
            }

            freeifaddrs(list);
        }
    }
#endif
}

/* ---- host: start listening ---- */

static void NetBeginHost(Game *game, int kind, int count, bool teams)
{
    NetStop();

    if (!NetSystemInit()) {
        NetSetNotice("Network is not available on this computer.");
        return;
    }

    NetSock s = socket(AF_INET, SOCK_STREAM, 0);

    if (s == NET_INVALID) {
        NetSetNotice("Could not create a network socket.");
        return;
    }

#if !defined(_WIN32)
    {
        int yes = 1;
        setsockopt(s, SOL_SOCKET, SO_REUSEADDR,
                   (const char *)&yes, sizeof(yes));
    }
#endif

    struct sockaddr_in addr;

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(NET_PORT);

    if (bind(s, (struct sockaddr *)&addr, sizeof(addr)) != 0 ||
        listen(s, 4) != 0) {

        NetCloseSock(s);
        NetSetNotice("Could not open port 7777 (is the game already running?)");
        return;
    }

    NetSetNonBlocking(s);

    for (int i = 0; i < NET_MAX_CLIENTS; i++)
        NetConnReset(&gNet.conns[i]);

    gNet.listenSock = s;
    gNet.role = NET_HOST;
    gNet.phase = NP_HOST_WAIT;
    gNet.seat = 0;
    gNet.hostKind = kind;
    gNet.hostCount = count;
    gNet.hostTeams = teams;

    NetDetectIPs();

    game->state = STATE_NET_LOBBY;
}

/* ---- client: type IP, then connect ---- */

static void NetBeginJoin(Game *game)
{
    NetStop();

    if (!NetSystemInit()) {
        NetSetNotice("Network is not available on this computer.");
        return;
    }

    for (int i = 0; i < NET_MAX_CLIENTS; i++)
        NetConnReset(&gNet.conns[i]);

    gNet.listenSock = NET_INVALID;
    gNet.role = NET_CLIENT;
    gNet.phase = NP_JOIN_INPUT;
    gNet.seat = 0;

    if (gNet.ipLen == 0) {
        snprintf(gNet.ip, sizeof(gNet.ip), "192.168.");
        gNet.ipLen = (int)strlen(gNet.ip);
    }

    /* throw away any keys typed earlier */
    while (GetCharPressed() > 0) { }

    game->state = STATE_NET_LOBBY;
}

static void NetBeginConnect(Game *game)
{
    (void)game;

    struct sockaddr_in addr;

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(NET_PORT);

    if (inet_pton(AF_INET, gNet.ip, &addr.sin_addr) != 1) {
        NetSetNotice("That is not a valid IP address.");
        return;
    }

    NetSock s = socket(AF_INET, SOCK_STREAM, 0);

    if (s == NET_INVALID) {
        NetSetNotice("Could not create a network socket.");
        return;
    }

    NetSetNonBlocking(s);
    NetSetNoDelay(s);

    int r = connect(s, (struct sockaddr *)&addr, sizeof(addr));

    if (r != 0 && !NetWouldBlock()) {
        NetCloseSock(s);
        NetSetNotice("Could not connect. Check the IP address.");
        return;
    }

    NetConnOpen(&gNet.conns[0], s);

    gNet.phase = NP_CONNECTING;
    gNet.connectTimer = 0.0f;
}

/* ---- sending a request from a joined player to the host ---- */

static void NetClientSend(int type, int arg)
{
    unsigned char b = (unsigned char)arg;
    NetConn *c = &gNet.conns[0];

    if (!c->used)
        return;

    NetQueue(c, type, &b, 1);
    NetFlush(c);
}

/* ---- host: a request from a joined player ---- */

static void NetHostHandle(
    Game *game, int slot, int type, const unsigned char *p, int len)
{
    int pid = PlayerOfSeat(game, slot + 1);

    if (pid < 0)
        return;

    if (type == MSG_ROLL) {
        if (game->state == STATE_SNAKES) {
            SnakeGame *s = &game->snake;

            if (s->state == SN_WAIT_ROLL && s->current == pid)
                StartSnakeRoll(s);
        } else if (game->state == STATE_WAIT_ROLL &&
                   game->currentPlayer == pid) {
            StartDiceRoll(game);
        }

    } else if (type == MSG_PICK) {
        if (len >= 1 &&
            game->state == STATE_CHOOSE_TOKEN &&
            game->currentPlayer == pid &&
            game->legalCount > 1)
            MoveToken(game, (int)p[0]);

    } else if (type == MSG_RESTART) {
        if (game->state == STATE_SNAKES)
            StartSnakes(game, false);
        else
            ResetGame(game);
    }
}

static void NetEndOnLostPlayer(Game *game, const char *text)
{
    NetStop();
    NetSetNotice(text);
    game->state = STATE_MENU;
    game->menuPage = MENU_MAIN;
}

/* Called once per frame. Does all the socket work. */
static void NetUpdate(Game *game, float dt)
{
    if (gNet.role == NET_OFF)
        return;

    /* ======================= HOST ======================= */
    if (gNet.role == NET_HOST) {

        int needed = gNet.hostCount - 1;

        if (gNet.phase == NP_HOST_WAIT) {

            /* accept new players */
            for (;;) {
                NetSock cs = accept(gNet.listenSock, NULL, NULL);

                if (cs == NET_INVALID)
                    break;

                int slot = -1;

                for (int i = 0; i < needed; i++) {
                    if (!gNet.conns[i].used) {
                        slot = i;
                        break;
                    }
                }

                if (slot < 0) {
                    NetCloseSock(cs);
                    continue;
                }

                NetSetNonBlocking(cs);
                NetSetNoDelay(cs);
                NetConnOpen(&gNet.conns[slot], cs);

                unsigned char hello[4] = {
                    (unsigned char)(slot + 1),
                    (unsigned char)gNet.hostKind,
                    (unsigned char)gNet.hostCount,
                    (unsigned char)(gNet.hostTeams ? 1 : 0)
                };

                NetQueue(&gNet.conns[slot], MSG_HELLO, hello, 4);
                NetFlush(&gNet.conns[slot]);
            }

            /* drop players who closed the window while waiting */
            int joined = 0;

            for (int i = 0; i < needed; i++) {
                NetConn *c = &gNet.conns[i];

                if (!c->used)
                    continue;

                bool ok = NetRecv(c);

                c->rxLen = 0;

                if (ok)
                    ok = NetFlush(c);

                if (!ok)
                    NetConnClose(c);
                else
                    joined++;
            }

            /* everybody is here -> start the game */
            if (joined >= needed) {
                if (gNet.listenSock != NET_INVALID) {
                    NetCloseSock(gNet.listenSock);
                    gNet.listenSock = NET_INVALID;
                }

                if (gNet.hostKind == KIND_SNAKES) {
                    SetPlayerCount(game, 2);
                    StartSnakes(game, false);
                } else {
                    StartLudo(game, gNet.hostCount, gNet.hostTeams, false);
                }

                gNet.phase = NP_PLAYING;
                gNet.sendTimer = NET_SEND_INTERVAL;
            }

            return;
        }

        if (gNet.phase != NP_PLAYING)
            return;

        /* requests from the joined players */
        for (int i = 0; i < needed; i++) {
            NetConn *c = &gNet.conns[i];
            unsigned char buf[NET_MSG_MAX];
            int type = 0, len = 0, r;

            if (!c->used) {
                NetEndOnLostPlayer(game, "A player left - the game ended.");
                return;
            }

            bool ok = NetRecv(c);

            while ((r = NetNextMsg(c, &type, buf, &len)) == 1)
                NetHostHandle(game, i, type, buf, len);

            if (r < 0)
                ok = false;

            if (!ok) {
                NetEndOnLostPlayer(game, "A player left - the game ended.");
                return;
            }
        }

        /* snapshots (about 30 per second) */
        gNet.sendTimer += dt;

        if (gNet.sendTimer >= NET_SEND_INTERVAL) {
            gNet.sendTimer = 0.0f;

            for (int i = 0; i < needed; i++) {
                NetConn *c = &gNet.conns[i];

                if (c->used && c->txLen == 0) {
                    unsigned char buf[NET_MSG_MAX];
                    int n = NetBuildSnapshot(
                        game, gSfxOut[i], buf, (int)sizeof(buf));

                    gSfxOut[i] = 0;
                    NetQueue(c, MSG_SNAP, buf, n);
                }
            }
        }

        for (int i = 0; i < needed; i++) {
            if (gNet.conns[i].used && !NetFlush(&gNet.conns[i])) {
                NetEndOnLostPlayer(game, "A player left - the game ended.");
                return;
            }
        }

        return;
    }

    /* ======================= CLIENT ======================= */
    NetConn *c = &gNet.conns[0];

    if (gNet.phase == NP_CONNECTING) {
        gNet.connectTimer += dt;

        fd_set wf, ef;
        struct timeval tv;

        FD_ZERO(&wf);
        FD_ZERO(&ef);
        FD_SET(c->sock, &wf);
        FD_SET(c->sock, &ef);

        tv.tv_sec = 0;
        tv.tv_usec = 0;

        int n = select((int)c->sock + 1, NULL, &wf, &ef, &tv);
        bool failed = false;

        if (n > 0) {
            int err = 0;
            NetLen el = (NetLen)sizeof(err);

            getsockopt(c->sock, SOL_SOCKET, SO_ERROR, (char *)&err, &el);

            if (FD_ISSET(c->sock, &ef) || err != 0)
                failed = true;
            else if (FD_ISSET(c->sock, &wf))
                gNet.phase = NP_CLIENT_WAIT;

        } else if (gNet.connectTimer > NET_CONNECT_TIMEOUT) {
            failed = true;
        }

        if (failed) {
            NetConnClose(c);
            gNet.phase = NP_JOIN_INPUT;
            NetSetNotice("Could not connect. Is the host waiting? Same Wi-Fi?");
        }

        return;
    }

    if (gNet.phase != NP_CLIENT_WAIT && gNet.phase != NP_PLAYING)
        return;

    for (int iter = 0; iter < 8; iter++) {
        unsigned char buf[NET_MSG_MAX];
        int type = 0, len = 0, r;
        bool any = false;
        bool ok = NetRecv(c);

        while ((r = NetNextMsg(c, &type, buf, &len)) == 1) {
            any = true;

            if (type == MSG_HELLO && len >= 4) {
                gNet.seat = buf[0];
                gNet.hostKind = buf[1];
                gNet.hostCount = buf[2];
                gNet.hostTeams = buf[3] != 0;
            } else if (type == MSG_SNAP) {
                if (NetApplySnapshot(game, buf, len))
                    gNet.phase = NP_PLAYING;
            }
        }

        if (r < 0)
            ok = false;

        if (!ok) {
            bool wasPlaying = (gNet.phase == NP_PLAYING);

            NetStop();
            NetSetNotice(wasPlaying
                ? "The host left the game."
                : "Disconnected from the host.");

            game->state = STATE_MENU;
            game->menuPage = MENU_MAIN;
            return;
        }

        if (!any)
            break;
    }

    if (!NetFlush(c)) {
        NetStop();
        NetSetNotice("Disconnected from the host.");
        game->state = STATE_MENU;
        game->menuPage = MENU_MAIN;
    }
}

/* ================================================================
   MENU ACTIONS
   ================================================================ */

static int MenuButtonCount(int page)
{
    switch (page) {
        case MENU_LUDO:   return 5;
        case MENU_ONLINE: return 6;
        case MENU_SNAKES: return 3;
        default:          return 4;
    }
}

static void MenuAction(Game *game, int i)
{
    PlaySfx(SFX_CLICK);

    switch (game->menuPage) {

        case MENU_MAIN:
            if (i == 0)
                game->menuPage = MENU_LUDO;
            else if (i == 1)
                game->menuPage = MENU_SNAKES;
            else if (i == 2)
                game->menuPage = MENU_ONLINE;
            else
                game->exitRequested = true;
            break;

        case MENU_LUDO:
            if (i == 0)
                StartLudo(game, 2, false, false);
            else if (i == 1)
                StartLudo(game, 4, false, false);
            else if (i == 2)
                StartLudo(game, 4, true, false);
            else if (i == 3)
                StartLudo(game, 2, false, true);
            else
                game->menuPage = MENU_MAIN;
            break;

        case MENU_ONLINE:
            if (i == 0)
                NetBeginHost(game, KIND_LUDO, 2, false);
            else if (i == 1)
                NetBeginHost(game, KIND_LUDO, 4, false);
            else if (i == 2)
                NetBeginHost(game, KIND_LUDO, 4, true);
            else if (i == 3)
                NetBeginHost(game, KIND_SNAKES, 2, false);
            else if (i == 4)
                NetBeginJoin(game);
            else
                game->menuPage = MENU_MAIN;
            break;

        case MENU_SNAKES:
        default:
            if (i == 0)
                StartSnakes(game, false);
            else if (i == 1)
                StartSnakes(game, true);
            else
                game->menuPage = MENU_MAIN;
            break;
    }
}

static void InitGame(Game *game)
{
    memset(game, 0, sizeof(*game));

    SetRandomSeed((unsigned int)time(NULL));

    gNet.listenSock = NET_INVALID;

    for (int i = 0; i < NET_MAX_CLIENTS; i++)
        NetConnReset(&gNet.conns[i]);

    game->players[PLAYER_RED] = (Player) {
        "RED", "Player 1", RED, RED_DARK, 0
    };

    game->players[PLAYER_BLUE] = (Player) {
        "BLUE", "Player 2", BLUE, BLUE_DARK, 26
    };

    game->players[PLAYER_GREEN] = (Player) {
        "GREEN", "Player 2", GREEN, GREEN_DARK, 13
    };

    game->players[PLAYER_YELLOW] = (Player) {
        "YELLOW", "Player 4", GOLD, GOLD_DARK, 39
    };

    StartGame(game, 2);
    game->state = STATE_MENU;
    game->menuPage = MENU_MAIN;
}

/* ================================================================
   UPDATE
   ================================================================ */

static void UpdateSnakes(
    Game *game, float dt, Vector2 mouse, bool click)
{
    SnakeGame *s = &game->snake;
    const Layout *L = &game->layout;

    if (s->toastTimer > 0.0f)
        s->toastTimer -= dt;

    if (IsKeyPressed(KEY_ESCAPE)) {
        ReturnToMenu(game);
        return;
    }

    if (IsKeyPressed(KEY_R)) {
        StartSnakes(game, s->vsComputer);
        return;
    }

    if (click) {
        if (s->state == SN_OVER) {

            if (CheckCollisionPointRec(mouse, L->winRestartButton)) {
                PlaySfx(SFX_CLICK);
                StartSnakes(game, s->vsComputer);
                return;
            }

            if (CheckCollisionPointRec(mouse, L->winMenuButton)) {
                PlaySfx(SFX_CLICK);
                ReturnToMenu(game);
                return;
            }

        } else {

            if (CheckCollisionPointRec(mouse, L->restartButton)) {
                PlaySfx(SFX_CLICK);
                StartSnakes(game, s->vsComputer);
                return;
            }

            if (CheckCollisionPointRec(mouse, L->menuButton)) {
                PlaySfx(SFX_CLICK);
                ReturnToMenu(game);
                return;
            }
        }
    }

    /* Roll button follows the active player's dice. */
    Rectangle activeCard = L->playerCard[s->current];
    float rollW = 150.0f;
    float rollH = 38.0f;

    game->layout.rollButton = (Rectangle) {
        L->diceBox[s->current].x - rollW - 14.0f,
        activeCard.y + (activeCard.height - rollH) * 0.5f,
        rollW,
        rollH
    };

    bool bot = s->vsComputer && s->current == 1;

    /* Online: only the player sitting at this computer may roll here.
       (The other player's roll arrives over the network.) */
    bool mine = LocalCanAct(game, s->current);

    switch (s->state) {

        case SN_WAIT_ROLL:
            if (bot) {
                s->timer += dt;

                if (s->timer >= BOT_DELAY)
                    StartSnakeRoll(s);
            } else if (mine && (IsKeyPressed(KEY_SPACE) ||
                (click &&
                 CheckCollisionPointRec(mouse, game->layout.rollButton)) ||
                (click &&
                 CheckCollisionPointRec(mouse, L->diceBox[s->current])))) {

                StartSnakeRoll(s);
            }
            break;

        case SN_ROLLING:
            s->timer += dt;
            s->faceTimer += dt;

            if (s->faceTimer >= 0.065f) {
                s->shown = GetRandomValue(1, 6);
                s->playerDice[s->current] = s->shown;
                s->faceTimer = 0.0f;
            }

            if (s->timer >= DICE_ROLL_TIME) {
                s->dice = GetRandomValue(1, 6);
                s->shown = s->dice;
                s->playerDice[s->current] = s->dice;
                s->timer = 0.0f;

                if (s->pos[s->current] == 0) {
                    /* Not started yet: only a 1 puts the piece
                       on square 1. */
                    if (s->dice == 1) {
                        s->stepsLeft = 1;
                        s->state = SN_MOVING;
                        SnakeToast(s, "Started! Entered square 1");
                    } else {
                        s->state = SN_NO_MOVE;
                        SnakeToast(s, "Need a 1 to start");
                    }
                } else if (s->pos[s->current] + s->dice > SNAKE_LAST) {
                    s->state = SN_NO_MOVE;
                    SnakeToast(s, "Need an exact roll to reach 100");
                } else {
                    s->stepsLeft = s->dice;
                    s->state = SN_MOVING;
                }
            }
            break;

        case SN_MOVING:
            s->timer += dt;

            if (s->timer >= STEP_TIME) {
                s->timer = 0.0f;

                s->pos[s->current]++;
                s->stepsLeft--;

                PlaySfx(SFX_STEP);

                if (s->stepsLeft <= 0) {
                    int to = JumpTarget(s->pos[s->current]);

                    if (to != 0) {
                        char text[64];

                        s->slideFrom = s->pos[s->current];
                        s->slideTo = to;
                        s->slideT = 0.0f;
                        s->state = SN_SLIDING;

                        if (to > s->slideFrom) {
                            snprintf(text, sizeof(text),
                                     "LADDER!  %d -> %d",
                                     s->slideFrom, to);
                            PlaySfx(SFX_LADDER);
                        } else {
                            snprintf(text, sizeof(text),
                                     "SNAKE!  %d -> %d",
                                     s->slideFrom, to);
                            PlaySfx(SFX_SNAKE);
                        }

                        SnakeToast(s, text);
                    } else {
                        FinishSnakeMove(s);
                    }
                }
            }
            break;

        case SN_SLIDING:
            s->slideT += dt / SLIDE_TIME;

            if (s->slideT >= 1.0f) {
                s->pos[s->current] = s->slideTo;
                FinishSnakeMove(s);
            }
            break;

        case SN_NO_MOVE:
            s->timer += dt;

            if (s->timer >= NO_MOVE_TIME)
                AdvanceSnakeTurn(s);
            break;

        case SN_OVER:
        default:
            break;
    }
}

/* Hosting / joining screen. */
static void LobbyCancel(Game *game)
{
    NetStop();
    game->state = STATE_MENU;
    game->menuPage = MENU_ONLINE;
}

static bool IsIpChar(int ch)
{
    return (ch >= '0' && ch <= '9') || ch == '.';
}

static void UpdateLobby(Game *game, Vector2 mouse, bool click)
{
    const Layout *L = &game->layout;

    if (IsKeyPressed(KEY_ESCAPE)) {
        LobbyCancel(game);
        return;
    }

    if (gNet.phase == NP_JOIN_INPUT) {
        int ch;

        while ((ch = GetCharPressed()) > 0) {
            if (IsIpChar(ch) && gNet.ipLen < 15) {
                gNet.ip[gNet.ipLen++] = (char)ch;
                gNet.ip[gNet.ipLen] = '\0';
            }
        }

        if ((IsKeyPressed(KEY_BACKSPACE) ||
             IsKeyPressedRepeat(KEY_BACKSPACE)) && gNet.ipLen > 0) {
            gNet.ip[--gNet.ipLen] = '\0';
        }

        /* Ctrl+V pastes an IP address */
        if ((IsKeyDown(KEY_LEFT_CONTROL) || IsKeyDown(KEY_RIGHT_CONTROL)) &&
            IsKeyPressed(KEY_V)) {

            const char *clip = GetClipboardText();

            if (clip) {
                gNet.ipLen = 0;
                gNet.ip[0] = '\0';

                for (int i = 0; clip[i] && gNet.ipLen < 15; i++) {
                    if (IsIpChar((unsigned char)clip[i])) {
                        gNet.ip[gNet.ipLen++] = clip[i];
                        gNet.ip[gNet.ipLen] = '\0';
                    }
                }
            }
        }

        if (IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_KP_ENTER) ||
            (click && CheckCollisionPointRec(mouse, L->menuBtn[3]))) {

            PlaySfx(SFX_CLICK);

            if (gNet.ipLen == 0)
                NetSetNotice("Type the host's IP address first.");
            else
                NetBeginConnect(game);

            return;
        }
    }

    if (click && CheckCollisionPointRec(mouse, L->menuBtn[4])) {
        PlaySfx(SFX_CLICK);
        LobbyCancel(game);
    }
}

/* A joined player's computer: it does NOT run the game rules.
   It only draws the host's snapshots and sends requests. */
static void UpdateClientPlay(
    Game *game, float dt, Vector2 mouse, bool click)
{
    const Layout *L = &game->layout;
    bool snakes = (game->state == STATE_SNAKES);
    int myPid = PlayerOfSeat(game, gNet.seat);
    int cur;
    bool over;

    if (IsKeyPressed(KEY_ESCAPE)) {
        ReturnToMenu(game);
        return;
    }

    if (snakes) {
        SnakeGame *s = &game->snake;

        if (s->toastTimer > 0.0f)
            s->toastTimer -= dt;

        /* smooth the slide between two snapshots */
        if (s->state == SN_SLIDING) {
            s->slideT += dt / SLIDE_TIME;

            if (s->slideT > 1.0f)
                s->slideT = 1.0f;
        }

        cur = s->current;
        over = (s->state == SN_OVER);
    } else {
        cur = game->currentPlayer;
        over = (game->state == STATE_GAME_OVER);
    }

    Rectangle activeCard = L->playerCard[cur];
    float rollW = (!snakes && game->numPlayers == 4) ? 120.0f : 150.0f;
    float rollH = 38.0f;

    game->layout.rollButton = (Rectangle) {
        L->diceBox[cur].x - rollW - 14.0f,
        activeCard.y + (activeCard.height - rollH) * 0.5f,
        rollW,
        rollH
    };

    if (click) {
        if (over) {
            if (CheckCollisionPointRec(mouse, L->winRestartButton)) {
                PlaySfx(SFX_CLICK);
                NetClientSend(MSG_RESTART, 0);
                return;
            }

            if (CheckCollisionPointRec(mouse, L->winMenuButton)) {
                PlaySfx(SFX_CLICK);
                ReturnToMenu(game);
                return;
            }
        } else {
            if (CheckCollisionPointRec(mouse, L->restartButton)) {
                PlaySfx(SFX_CLICK);
                NetClientSend(MSG_RESTART, 0);
                return;
            }

            if (CheckCollisionPointRec(mouse, L->menuButton)) {
                PlaySfx(SFX_CLICK);
                ReturnToMenu(game);
                return;
            }
        }
    }

    if (over || cur != myPid)
        return;

    bool rollClick =
        click &&
        (CheckCollisionPointRec(mouse, game->layout.rollButton) ||
         CheckCollisionPointRec(mouse, L->diceBox[cur]));

    if (snakes) {
        if (game->snake.state == SN_WAIT_ROLL &&
            (IsKeyPressed(KEY_SPACE) || rollClick))
            NetClientSend(MSG_ROLL, 0);

        return;
    }

    if (game->state == STATE_WAIT_ROLL) {
        if (IsKeyPressed(KEY_SPACE) || rollClick)
            NetClientSend(MSG_ROLL, 0);

    } else if (game->state == STATE_CHOOSE_TOKEN &&
               game->legalCount > 1 && click) {

        int best = -1;
        float bestDist = 999999.0f;

        for (int t = 0; t < TOKENS_PER_PLAYER; t++) {
            if (!game->legal[t])
                continue;

            Vector2 center;
            float radius;

            GetTokenScreenInfo(game, game->mover, t, &center, &radius);

            float dx = mouse.x - center.x;
            float dy = mouse.y - center.y;
            float dist = sqrtf(dx * dx + dy * dy);

            if (dist <= radius * 1.55f && dist < bestDist) {
                best = t;
                bestDist = dist;
            }
        }

        if (best >= 0)
            NetClientSend(MSG_PICK, best);
    }
}

static void UpdateGame(Game *game)
{
    float dt = GetFrameTime();

    game->animationTime += dt;

    if (gNet.noticeTimer > 0.0f)
        gNet.noticeTimer -= dt;

    if (IsKeyPressed(KEY_M))
        gMuted = !gMuted;

    /* Wi-Fi play: sockets, joining, snapshots, requests */
    NetUpdate(game, dt);

    game->layout =
        ComputeLayout(
            GetScreenWidth(),
            GetScreenHeight(),
            game->state == STATE_SNAKES ? 2 : game->numPlayers);

    Vector2 mouse = GetMousePosition();

    bool click =
        IsMouseButtonPressed(MOUSE_BUTTON_LEFT);

    if (game->state == STATE_NET_LOBBY) {
        UpdateLobby(game, mouse, click);
        return;
    }

    /* A joined player only displays the host's game. */
    if (gNet.role == NET_CLIENT && gNet.phase == NP_PLAYING &&
        game->state != STATE_MENU) {

        UpdateClientPlay(game, dt, mouse, click);
        return;
    }

    if (game->state == STATE_SNAKES) {
        UpdateSnakes(game, dt, mouse, click);
        return;
    }

    Rectangle activeCard =
        game->layout.playerCard[game->currentPlayer];

    float rollW = (game->numPlayers == 4) ? 120.0f : 150.0f;
    float rollH = 38.0f;

    game->layout.rollButton = (Rectangle) {
        game->layout.diceBox[game->currentPlayer].x
            - rollW - 14.0f,
        activeCard.y + (activeCard.height - rollH) * 0.5f,
        rollW,
        rollH
    };

    if (game->state == STATE_MENU) {

        if (IsKeyPressed(KEY_ESCAPE)) {
            if (game->menuPage != MENU_MAIN)
                game->menuPage = MENU_MAIN;
            else
                game->exitRequested = true;
        }

        if (IsKeyPressed(KEY_ENTER)) {
            PlaySfx(SFX_CLICK);
            StartGame(game, 2);
            return;
        }

        if (IsKeyPressed(KEY_FOUR) || IsKeyPressed(KEY_KP_4)) {
            PlaySfx(SFX_CLICK);
            StartGame(game, 4);
            return;
        }

        if (click) {
            int count = MenuButtonCount(game->menuPage);

            for (int i = 0; i < count; i++) {
                if (CheckCollisionPointRec(
                        mouse,
                        game->layout.menuBtn[i])) {

                    MenuAction(game, i);
                    break;
                }
            }
        }

        return;
    }

    if (IsKeyPressed(KEY_ESCAPE)) {
        ReturnToMenu(game);
        return;
    }

    if (IsKeyPressed(KEY_R)) {
        ResetGame(game);
        return;
    }

    /* Global buttons */
    if (click) {
        if (game->state == STATE_GAME_OVER) {

            if (CheckCollisionPointRec(
                    mouse,
                    game->layout.winRestartButton)) {

                PlaySfx(SFX_CLICK);
                ResetGame(game);
                return;
            }

            if (CheckCollisionPointRec(
                    mouse,
                    game->layout.winMenuButton)) {

                PlaySfx(SFX_CLICK);
                ReturnToMenu(game);
                return;
            }

        } else {

            if (CheckCollisionPointRec(
                    mouse,
                    game->layout.restartButton)) {

                PlaySfx(SFX_CLICK);
                ResetGame(game);
                return;
            }

            if (CheckCollisionPointRec(
                    mouse,
                    game->layout.menuButton)) {

                PlaySfx(SFX_CLICK);
                ReturnToMenu(game);
                return;
            }
        }
    }

    bool botTurn = game->isBot[game->currentPlayer];

    /* Online: only the player sitting at this computer may act here.
       (Joined players' requests arrive over the network.) */
    bool mine = LocalCanAct(game, game->currentPlayer);

    switch (game->state) {

        case STATE_WAIT_ROLL:
            if (botTurn) {
                game->timer += dt;

                if (game->timer >= BOT_DELAY)
                    StartDiceRoll(game);

            } else if (mine && (IsKeyPressed(KEY_SPACE) ||
                (click &&
                 CheckCollisionPointRec(
                    mouse,
                    game->layout.rollButton)) ||
                (click &&
                 CheckCollisionPointRec(
                    mouse,
                    game->layout.diceBox[game->currentPlayer])))) {

                StartDiceRoll(game);
            }
            break;

        case STATE_DICE_ROLLING:

            game->timer += dt;
            game->faceTimer += dt;

            if (game->faceTimer >= 0.065f) {
                game->shownDice =
                    GetRandomValue(1, 6);

                game->playerDice[game->currentPlayer] =
                    game->shownDice;

                game->faceTimer = 0.0f;
            }

            if (game->timer >= DICE_ROLL_TIME)
                RollDice(game);

            break;

        case STATE_CHOOSE_TOKEN: {

            if (game->legalCount == 1) {
                game->timer += dt;

                if (game->timer >= AUTO_MOVE_DELAY) {
                    for (int t = 0;
                         t < TOKENS_PER_PLAYER;
                         t++) {

                        if (game->legal[t]) {
                            MoveToken(game, t);
                            break;
                        }
                    }
                }

                break;
            }

            /* Computer picks the best token by itself. */
            if (botTurn) {
                game->timer += dt;

                if (game->timer >= BOT_DELAY) {
                    int pick = BotChooseToken(game);

                    if (pick >= 0)
                        MoveToken(game, pick);
                }

                break;
            }

            if (!click || !mine)
                break;

            int best = -1;
            float bestDist = 999999.0f;

            for (int t = 0;
                 t < TOKENS_PER_PLAYER;
                 t++) {

                if (!game->legal[t])
                    continue;

                Vector2 center;
                float radius;

                GetTokenScreenInfo(
                    game,
                    game->mover,
                    t,
                    &center,
                    &radius);

                float dx = mouse.x - center.x;
                float dy = mouse.y - center.y;

                float dist = sqrtf(dx * dx + dy * dy);

                if (dist <= radius * 1.55f &&
                    dist < bestDist) {

                    best = t;
                    bestDist = dist;
                }
            }

            if (best >= 0)
                MoveToken(game, best);

            break;
        }

        case STATE_TOKEN_MOVING: {

            game->timer += dt;

            if (game->timer >= STEP_TIME) {

                game->timer = 0.0f;

                Token *token =
                    &game->players
                        [game->mover]
                        .tokens[game->movingToken];

                if (token->pos == POS_BASE)
                    token->pos = 0;
                else
                    token->pos++;

                PlaySfx(SFX_STEP);

                game->stepsLeft--;

                if (game->stepsLeft <= 0)
                    FinishMove(game);
            }

            break;
        }

        case STATE_NO_MOVES:

            game->timer += dt;

            if (game->timer >= NO_MOVE_TIME)
                AdvanceTurn(game, "");

            break;

        case STATE_GAME_OVER:
        default:
            break;
    }
}

/* ================================================================
   DRAW HELPERS
   ================================================================ */

static Color ColorMix(Color a, Color b, float amount)
{
    if (amount < 0) amount = 0;
    if (amount > 1) amount = 1;

    Color c;

    c.r = (unsigned char)((float)a.r +
          ((float)b.r - a.r) * amount);
    c.g = (unsigned char)((float)a.g +
          ((float)b.g - a.g) * amount);
    c.b = (unsigned char)((float)a.b +
          ((float)b.b - a.b) * amount);
    c.a = 255;

    return c;
}

static void DrawVerticalGradient(
    int width,
    int height,
    Color top,
    Color bottom)
{
    for (int y = 0; y < height; y++) {
        float t = (float)y / (float)height;
        DrawRectangle(
            0, y, width, 1,
            ColorMix(top, bottom, t));
    }
}

static void DrawShadowRect(
    Rectangle r,
    float roundness,
    float alpha)
{
    DrawRectangleRounded(
        (Rectangle){
            r.x + 5,
            r.y + 8,
            r.width,
            r.height
        },
        roundness,
        12,
        Fade(BLACK, alpha));
}

static void DrawModernButton(
    Rectangle r,
    const char *text,
    Color color,
    bool enabled,
    int fontSize)
{
    bool hover =
        enabled &&
        CheckCollisionPointRec(
            GetMousePosition(), r);

    Color fill = enabled
        ? (hover ? ColorBrightness(color, 0.15f)
                 : color)
        : (Color){90, 96, 115, 255};

    DrawShadowRect(r, 0.25f, 0.30f);

    DrawRectangleRounded(
        r,
        0.25f,
        12,
        fill);

    if (hover && enabled) {
        DrawRectangleRoundedLinesEx(
            r,
            0.25f,
            12,
            2.0f,
            Fade(WHITE, 0.35f));
    }

    int tw = MeasureText(text, fontSize);

    DrawText(
        text,
        (int)(r.x + (r.width - tw) * 0.5f),
        (int)(r.y + (r.height - fontSize) * 0.5f),
        fontSize,
        WHITE_SOFT);
}

static void DrawCenteredText(
    const char *text,
    float x,
    float y,
    int fontSize,
    Color color)
{
    int w = MeasureText(text, fontSize);

    DrawText(
        text,
        (int)(x - w * 0.5f),
        (int)y,
        fontSize,
        color);
}

static void DrawTextWrapped(
    const char *text,
    int x,
    int y,
    int maxWidth,
    int fontSize,
    Color color)
{
    char line[MSG_LEN] = "";
    char word[64];

    int lineNo = 0;
    int lineHeight = fontSize + 5;

    const char *p = text;

    while (*p) {

        while (*p == ' ')
            p++;

        int n = 0;

        while (*p && *p != ' ' && n < 63)
            word[n++] = *p++;

        word[n] = '\0';

        if (n == 0)
            break;

        char test[MSG_LEN];

        snprintf(
            test,
            sizeof(test),
            "%s%s%s",
            line,
            line[0] ? " " : "",
            word);

        if (line[0] &&
            MeasureText(test, fontSize) > maxWidth) {

            DrawText(
                line,
                x,
                y + lineNo * lineHeight,
                fontSize,
                color);

            lineNo++;

            snprintf(
                line,
                sizeof(line),
                "%s",
                word);

        } else {

            snprintf(
                line,
                sizeof(line),
                "%s",
                test);
        }
    }

    if (line[0]) {
        DrawText(
            line,
            x,
            y + lineNo * lineHeight,
            fontSize,
            color);
    }
}

/* ================================================================
   BOARD (LUDO)
   ================================================================ */

static void DrawStar(
    Vector2 center,
    float outer,
    Color color)
{
    Vector2 points[10];

    for (int i = 0; i < 10; i++) {
        float radius =
            (i % 2 == 0)
            ? outer
            : outer * 0.45f;

        float angle =
            -PI / 2.0f -
            (float)i * PI / 5.0f;

        points[i] = (Vector2) {
            center.x + cosf(angle) * radius,
            center.y + sinf(angle) * radius
        };
    }

    for (int i = 0; i < 10; i++)
        DrawTriangle(
            center,
            points[i],
            points[(i + 1) % 10],
            color);
}

static void DrawYard(
    const Layout *L,
    int qx,
    int qy,
    Color color,
    bool active)
{
    float c = L->cell;

    Vector2 origin =
        GridToScreen(L, (float)qx, (float)qy);

    Rectangle outer = {
        origin.x,
        origin.y,
        c * 6.0f,
        c * 6.0f
    };

    Rectangle inner = {
        origin.x + c * 0.55f,
        origin.y + c * 0.55f,
        c * 4.9f,
        c * 4.9f
    };

    /* Active yards use their strong player color. Inactive yards use
       a darker modern tint instead of looking disabled/grey. */
    Color yardColor = active
        ? color
        : ColorMix(INACTIVE_INNER, color, 0.48f);

    DrawRectangleRec(outer, yardColor);

    if (active) {
        DrawRectangleRounded(
            inner,
            0.10f,
            8,
            Fade(WHITE, 0.98f));
    } else {
        /* Dark glass-like inner area keeps the inactive zone colorful
           while clearly separating it from the playable yards. */
        DrawRectangleRounded(
            inner,
            0.10f,
            8,
            ColorMix(INACTIVE_INNER, color, 0.22f));

        DrawRectangleRoundedLinesEx(
            inner,
            0.10f,
            8,
            1.5f,
            Fade(color, 0.35f));
    }

    DrawRectangleRoundedLinesEx(
        outer,
        0.06f,
        8,
        active ? 3.0f : 2.0f,
        active ? Fade(WHITE, 0.65f) : Fade(color, 0.55f));

    for (int k = 0; k < 4; k++) {

        Vector2 pos =
            GridToScreen(
                L,
                qx + YARD_SLOT[k][0],
                qy + YARD_SLOT[k][1]);

        if (active) {
            DrawCircleV(
                pos,
                c * 0.48f,
                Fade(color, 0.18f));

            DrawCircleLines(
                (int)pos.x,
                (int)pos.y,
                c * 0.48f,
                Fade(color, 0.45f));
        } else {
            DrawCircleV(
                pos,
                c * 0.48f,
                Fade(BLACK, 0.18f));

            DrawCircleLines(
                (int)pos.x,
                (int)pos.y,
                c * 0.48f,
                Fade(color, 0.38f));
        }
    }
}

static void DrawBoard(const Game *game)
{
    const Layout *L = &game->layout;

    float c = L->cell;

    bool four = (game->numPlayers == 4);

    Rectangle board = {
        L->boardOrigin.x,
        L->boardOrigin.y,
        L->boardSize,
        L->boardSize
    };

    /* Board shadow */
    DrawRectangleRounded(
        (Rectangle){
            board.x + 8,
            board.y + 10,
            board.width,
            board.height
        },
        0.025f,
        12,
        Fade(BLACK, 0.40f));

    DrawRectangleRounded(
        board,
        0.025f,
        12,
        BOARD_WHITE);

    bool playing =
        game->state != STATE_MENU &&
        game->state != STATE_NET_LOBBY &&
        game->state != STATE_GAME_OVER;

    DrawYard(
        L, 0, 0,
        RED,
        playing && game->currentPlayer == PLAYER_RED);

    DrawYard(
        L, 9, 9,
        BLUE,
        playing && game->currentPlayer == PLAYER_BLUE);

    if (four) {
        /* In a 4-player game the top-right and bottom-left yards
           belong to GREEN and YELLOW. */
        DrawYard(
            L, 9, 0,
            GREEN,
            playing && game->currentPlayer == PLAYER_GREEN);

        DrawYard(
            L, 0, 9,
            GOLD,
            playing && game->currentPlayer == PLAYER_YELLOW);
    } else {
        /* Non-playing corners remain colorful, but use a darker modern
           treatment so players can immediately distinguish them from
           the active Red/Blue yards. */
        DrawYard(L, 9, 0, INACTIVE_GREEN, false);
        DrawYard(L, 0, 9, INACTIVE_GOLD, false);
    }

    /* Main 52-cell track */
    for (int i = 0; i < RING_SIZE; i++) {

        int col = RING_CELLS[i][0];
        int row = RING_CELLS[i][1];

        Rectangle cell = CellRect(L, col, row);

        Color fill = WHITE;

        if (i == 0)
            fill = RED;
        else if (i == 26)
            fill = BLUE;
        else if (i == 13)
            fill = four ? GREEN : Fade(GREEN, 0.62f);
        else if (i == 39)
            fill = four ? GOLD : Fade(GOLD, 0.70f);

        DrawRectangleRec(cell, fill);

        DrawRectangleLinesEx(
            cell,
            1.0f,
            Fade(BOARD_LINE, 0.90f));

        if (IsSafeRingIndex(i)) {

            Vector2 center = {
                cell.x + c * 0.5f,
                cell.y + c * 0.5f
            };

            DrawCircleV(
                center,
                c * 0.34f,
                Fade(BLACK, 0.06f));

            bool startCell =
                i == 0 || i == 26 ||
                (four && (i == 13 || i == 39));

            DrawStar(
                center,
                c * 0.28f,
                startCell
                    ? WHITE
                    : Fade(DARKGRAY, 0.55f));
        }
    }

    /* Home lanes */
    for (int k = 0; k < 5; k++) {

        Rectangle lanes[2] = {
            CellRect(L, 1 + k, 7),
            CellRect(L, 13 - k, 7)
        };

        Color colors[2] = {
            Fade(RED, 0.78f),
            Fade(BLUE, 0.78f)
        };

        for (int i = 0; i < 2; i++) {

            DrawRectangleRec(
                lanes[i],
                colors[i]);

            DrawRectangleLinesEx(
                lanes[i],
                1.0f,
                Fade(WHITE, 0.45f));
        }

        /* Extra home lanes used only in a 4-player game. */
        if (four) {

            Rectangle lanes4[2] = {
                CellRect(L, 7, 1 + k),
                CellRect(L, 7, 13 - k)
            };

            Color colors4[2] = {
                Fade(GREEN, 0.78f),
                Fade(GOLD, 0.78f)
            };

            for (int i = 0; i < 2; i++) {

                DrawRectangleRec(
                    lanes4[i],
                    colors4[i]);

                DrawRectangleLinesEx(
                    lanes4[i],
                    1.0f,
                    Fade(WHITE, 0.45f));
            }
        }
    }

    /* Center */
    Vector2 tl = GridToScreen(L, 6, 6);
    Vector2 tr = GridToScreen(L, 9, 6);
    Vector2 bl = GridToScreen(L, 6, 9);
    Vector2 br = GridToScreen(L, 9, 9);
    Vector2 mid = GridToScreen(L, 7.5f, 7.5f);

    DrawTriangle(tl, bl, mid, RED);
    DrawTriangle(bl, br, mid, GOLD);
    DrawTriangle(br, tr, mid, BLUE);
    DrawTriangle(tr, tl, mid, Fade(GREEN, 0.80f));

    DrawLineV(
        tl, br,
        Fade(WHITE, 0.90f));

    DrawLineV(
        tr, bl,
        Fade(WHITE, 0.90f));

    DrawRectangleRoundedLinesEx(
        board,
        0.025f,
        12,
        3.0f,
        Fade((Color){110,120,145,255}, 0.75f));
}

/* ================================================================
   TOKENS
   ================================================================ */

static void DrawToken(
    const Game *game,
    int player,
    int token,
    bool selected)
{
    Vector2 center;
    float radius;

    GetTokenScreenInfo(
        game,
        player,
        token,
        &center,
        &radius);

    Color color =
        game->players[player].color;

    /* Strong animated treatment for a token that can legally move.
       The playable pieces should be impossible to miss. */
    if (selected) {

        float pulse =
            0.5f +
            0.5f * sinf(
                (float)GetTime() * 7.0f);

        float glowRadius =
            radius * (1.72f + pulse * 0.18f);

        /* Soft outer glow */
        DrawCircleV(
            center,
            glowRadius,
            Fade(GOLD, 0.10f + pulse * 0.05f));

        DrawCircleV(
            center,
            radius * 1.38f,
            Fade(color, 0.18f));

        /* Double animated rings */
        DrawRing(
            center,
            radius * 1.12f,
            radius * (1.25f + pulse * 0.08f),
            0,
            360,
            48,
            GOLD);

        DrawRing(
            center,
            radius * 1.34f,
            radius * 1.39f,
            0,
            360,
            48,
            Fade(WHITE, 0.90f));
    }

    /* Shadow */
    DrawCircleV(
        (Vector2){
            center.x + 3,
            center.y + 5
        },
        radius,
        Fade(BLACK, 0.28f));

    /* Make legal/selectable tokens slightly larger and brighter. */
    float drawRadius = selected
        ? radius * 1.08f
        : radius;

    /* Outer rim */
    DrawCircleV(
        center,
        drawRadius,
        selected ? GOLD : game->players[player].darkColor);

    /* Main body */
    DrawCircleV(
        center,
        drawRadius * 0.84f,
        color);

    /* Extra white outline for legal tokens */
    if (selected) {
        DrawCircleLines(
            (int)center.x,
            (int)center.y,
            drawRadius * 0.88f,
            Fade(WHITE, 0.95f));
    }

    /* Inner highlight */
    DrawCircleV(
        (Vector2){
            center.x - drawRadius * 0.27f,
            center.y - drawRadius * 0.30f
        },
        drawRadius * 0.23f,
        Fade(WHITE, 0.50f));

    /* Small center detail */
    DrawCircleV(
        center,
        drawRadius * 0.15f,
        Fade(WHITE, 0.16f));

    if (selected) {
        const char *label = "MOVE";
        int fontSize = 9;
        int tw = MeasureText(label, fontSize);

        DrawRectangleRounded(
            (Rectangle){
                center.x - tw * 0.5f - 7.0f,
                center.y - drawRadius - 23.0f,
                tw + 14.0f,
                18.0f
            },
            0.45f,
            8,
            GOLD);

        DrawText(
            label,
            (int)(center.x - tw * 0.5f),
            (int)(center.y - drawRadius - 19.0f),
            fontSize,
            (Color){35, 35, 45, 255});
    }
}

static void DrawTokens(const Game *game)
{
    bool selecting =
        game->state == STATE_CHOOSE_TOKEN;

    /* Draw non-selected first */
    for (int i = 0; i < game->numPlayers; i++) {
        int p = game->order[i];

        for (int t = 0; t < TOKENS_PER_PLAYER; t++) {

            bool selected =
                p == game->mover &&
                selecting &&
                game->legal[t];

            if (!selected)
                DrawToken(game, p, t, false);
        }
    }

    /* Draw active tokens on top */
    for (int i = 0; i < game->numPlayers; i++) {
        int p = game->order[i];

        for (int t = 0; t < TOKENS_PER_PLAYER; t++) {

            bool selected =
                p == game->mover &&
                selecting &&
                game->legal[t];

            bool moving =
                p == game->mover &&
                game->state == STATE_TOKEN_MOVING &&
                t == game->movingToken;

            if (selected || moving)
                DrawToken(game, p, t, true);
        }
    }
}

/* ================================================================
   DICE
   ================================================================ */

static const unsigned short PIP_MASK[7] = {
    0x000,
    0x010,
    0x101,
    0x111,
    0x145,
    0x155,
    0x16D
};

static void DrawDice(
    Rectangle box,
    int value,
    Color accent,
    bool rolling,
    bool enabled)
{
    if (value < 0 || value > 6)
        value = 0;

    float bounce =
        rolling
        ? sinf((float)GetTime() * 22.0f) * 3.0f
        : 0.0f;

    box.y += bounce;

    Color borderColor = enabled
        ? accent
        : (Color){85, 94, 118, 255};

    Color faceColor = enabled
        ? WHITE_SOFT
        : (Color){105, 112, 130, 255};

    DrawRectangleRounded(
        (Rectangle){
            box.x + 6,
            box.y + 9,
            box.width,
            box.height
        },
        0.18f,
        12,
        Fade(BLACK, enabled ? 0.35f : 0.20f));

    DrawRectangleRounded(
        box,
        0.18f,
        12,
        faceColor);

    DrawRectangleRoundedLinesEx(
        box,
        0.18f,
        12,
        4.0f,
        borderColor);

    for (int slot = 0; slot < 9; slot++) {

        if (!(PIP_MASK[value] &
              (1u << slot)))
            continue;

        float px =
            box.x +
            box.width *
            (0.25f +
             0.25f * (float)(slot % 3));

        float py =
            box.y +
            box.height *
            (0.25f +
             0.25f * (float)(slot / 3));

        DrawCircle(
            (int)px,
            (int)py,
            box.width * 0.070f,
            enabled
                ? (Color){35, 40, 58, 255}
                : (Color){70, 75, 90, 255});
    }

    if (value == 0) {
        int fs = (int)(box.height * 0.45f);

        DrawCenteredText(
            "?",
            box.x + box.width * 0.5f,
            box.y + box.height * 0.25f,
            fs,
            enabled ? TEXT_MUTED : (Color){125, 130, 145, 255});
    }

    /* Disabled overlay makes it obvious that this player's die
       cannot be used during the opponent's turn. */
    if (!enabled) {
        DrawRectangleRounded(
            box,
            0.18f,
            12,
            Fade(BLACK, 0.38f));

        DrawCenteredText(
            "WAIT",
            box.x + box.width * 0.5f,
            box.y + box.height * 0.40f,
            13,
            Fade(WHITE, 0.75f));
    }
}

/* ================================================================
   PLAYER CARD / SIDE PANEL
   ================================================================ */

/* Small "(YOU)" tag next to the name, only while playing over Wi-Fi. */
static void DrawYouTag(const Game *game, int player, Rectangle r, const char *name)
{
    if (!NetIsMe(game, player))
        return;

    int nw = MeasureText(name, 18);

    DrawText(
        "(YOU)",
        (int)(r.x + 46 + nw + 8),
        (int)(r.y + 14),
        10,
        GOLD);
}

static void DrawPlayerCard(
    const Game *game,
    int player,
    Rectangle r)
{
    const Player *p = &game->players[player];

    bool active =
        game->currentPlayer == player &&
        game->state != STATE_MENU &&
        game->state != STATE_GAME_OVER;

    Color cardColor = active
        ? Fade(p->color, 0.18f)
        : Fade(PANEL_2, 0.92f);

    DrawShadowRect(r, 0.12f, 0.35f);

    DrawRectangleRounded(r, 0.12f, 12, cardColor);

    DrawRectangleRoundedLinesEx(
        r,
        0.12f,
        12,
        active ? 3.0f : 1.0f,
        active ? Fade(p->color, 0.90f)
               : Fade(WHITE, 0.10f));

    /* Player color marker */
    DrawCircleV(
        (Vector2){r.x + 24.0f, r.y + r.height * 0.5f},
        12.0f,
        p->color);

    DrawCircleV(
        (Vector2){r.x + 21.0f, r.y + r.height * 0.5f - 4.0f},
        3.0f,
        Fade(WHITE, 0.65f));

    DrawText(
        p->name,
        (int)(r.x + 46),
        (int)(r.y + 10),
        18,
        WHITE_SOFT);

    DrawYouTag(game, player, r, p->name);

    DrawText(
        p->subtitle,
        (int)(r.x + 46),
        (int)(r.y + 32),
        10,
        TEXT_MUTED);

    int done = CountFinished(game, player);
    int home = CountHome(game, player);

    char status[80];
    snprintf(
        status,
        sizeof(status),
        "%d/4 HOME   •   %d in yard",
        done,
        home);

    DrawText(
        status,
        (int)(r.x + 46),
        (int)(r.y + 48),
        9,
        active ? Fade(p->color, 0.95f) : TEXT_MUTED);

    /* Compact progress bar */
    Rectangle bar = {
        r.x + 46,
        r.y + r.height - 7,
        100.0f,
        3.0f
    };

    DrawRectangleRounded(
        bar, 0.5f, 4, Fade(WHITE, 0.10f));

    Rectangle progress = bar;
    progress.width *= (float)done / 4.0f;

    DrawRectangleRounded(
        progress, 0.5f, 4, p->color);

    /* Active turn badge (sits closer to the name in 4-player mode,
       where the cards are narrower). */
    if (active) {
        const char *badge = "YOUR TURN";

        if (game->state == STATE_DICE_ROLLING)
            badge = "ROLLING";
        else if (game->state == STATE_WAIT_ROLL &&
                 game->isBot[player])
            badge = "THINKING";
        else if (game->mover != player &&
                 (game->state == STATE_CHOOSE_TOKEN ||
                  game->state == STATE_TOKEN_MOVING))
            badge = "TEAMMATE";
        else if (gNet.role != NET_OFF && !NetIsMe(game, player))
            badge = "THEIR TURN";

        float badgeX = (game->numPlayers == 4) ? 130.0f : 180.0f;

        DrawRectangleRounded(
            (Rectangle){r.x + badgeX, r.y + 15, 82, 24},
            0.5f,
            8,
            Fade(p->color, 0.20f));

        DrawCenteredText(
            badge,
            r.x + badgeX + 41.0f,
            r.y + 20,
            9,
            p->color);
    }
}

/* MENU / RESTART sidebar (shared by Ludo and Snakes & Ladders). */
static void DrawSideBar(const Layout *L)
{
    DrawShadowRect(L->sideBar, 0.18f, 0.28f);
    DrawRectangleRounded(
        L->sideBar, 0.18f, 12, Fade(PANEL, 0.92f));
    DrawRectangleRoundedLinesEx(
        L->sideBar, 0.18f, 12, 1.0f, Fade(WHITE, 0.08f));

    DrawCenteredText(
        "GAME",
        L->sideBar.x + L->sideBar.width * 0.5f,
        L->sideBar.y - 18.0f,
        9,
        TEXT_MUTED);

    DrawModernButton(
        L->menuButton,
        "MENU",
        GREY_BTN,
        true,
        10);

    DrawModernButton(
        L->restartButton,
        "RESTART",
        GREEN,
        true,
        10);
}

static void DrawPanel(const Game *game)
{
    const Layout *L = &game->layout;

    /* The screenshot-inspired UI uses player cards above and below
       the board instead of a large side panel. */
    for (int i = 0; i < game->numPlayers; i++) {
        int pId = game->order[i];

        DrawPlayerCard(
            game,
            pId,
            L->playerCard[pId]);

        bool activeDie =
            game->currentPlayer == pId &&
            game->state != STATE_GAME_OVER;

        int shown =
            (game->state == STATE_DICE_ROLLING &&
             game->currentPlayer == pId)
                ? game->shownDice
                : game->playerDice[pId];

        DrawCenteredText(
            "DICE",
            L->diceBox[pId].x + L->diceBox[pId].width * 0.5f,
            L->diceBox[pId].y - 7.0f,
            7,
            activeDie ? game->players[pId].color : TEXT_MUTED);

        DrawDice(
            L->diceBox[pId],
            shown,
            game->players[pId].color,
            activeDie && game->state == STATE_DICE_ROLLING,
            activeDie);
    }

    /* Roll button belongs only to the active player. */
    const Player *current =
        &game->players[game->currentPlayer];

    bool rollEnabled =
        game->state == STATE_WAIT_ROLL &&
        !game->isBot[game->currentPlayer] &&
        LocalCanAct(game, game->currentPlayer);

    DrawModernButton(
        L->rollButton,
        rollEnabled
            ? "ROLL DICE"
            : "WAIT...",
        current->color,
        rollEnabled,
        15);

    /* Dedicated side bar for utility controls. */
    DrawSideBar(L);
}

/* ================================================================
   SNAKES & LADDERS DRAWING
   ================================================================ */

static Vector2 SnakeCellCenter(const Layout *L, int n)
{
    if (n < 1) n = 1;
    if (n > SNAKE_LAST) n = SNAKE_LAST;

    float cell = L->boardSize / (float)SNAKE_BOARD_N;

    int idx = n - 1;
    int row = idx / SNAKE_BOARD_N;
    int col = idx % SNAKE_BOARD_N;

    if (row % 2 == 1)
        col = SNAKE_BOARD_N - 1 - col;

    return (Vector2) {
        L->boardOrigin.x + ((float)col + 0.5f) * cell,
        L->boardOrigin.y +
            ((float)(SNAKE_BOARD_N - 1 - row) + 0.5f) * cell
    };
}

static void DrawLadderShape(const Layout *L, int from, int to)
{
    float cell = L->boardSize / (float)SNAKE_BOARD_N;

    Vector2 a = SnakeCellCenter(L, from);
    Vector2 b = SnakeCellCenter(L, to);

    float dx = b.x - a.x;
    float dy = b.y - a.y;
    float len = sqrtf(dx * dx + dy * dy);

    if (len < 1.0f)
        return;

    Vector2 u = {dx / len, dy / len};
    Vector2 n = {-u.y, u.x};

    /* Shorten slightly so the ladder sits inside the cells. */
    Vector2 s = {a.x + u.x * cell * 0.20f, a.y + u.y * cell * 0.20f};
    Vector2 e = {b.x - u.x * cell * 0.20f, b.y - u.y * cell * 0.20f};
    float sl = len - cell * 0.40f;

    float off = cell * 0.16f;
    float rail = fmaxf(3.0f, cell * 0.075f);

    Color railColor = (Color){160, 96, 40, 255};
    Color rungColor = (Color){214, 158, 86, 255};

    /* Rungs first, rails on top. */
    int rungs = (int)(sl / (cell * 0.30f));

    for (int i = 1; i <= rungs; i++) {
        float t = (float)i / (float)(rungs + 1);

        Vector2 p = {s.x + u.x * sl * t, s.y + u.y * sl * t};

        DrawLineEx(
            (Vector2){p.x - n.x * off, p.y - n.y * off},
            (Vector2){p.x + n.x * off, p.y + n.y * off},
            rail * 0.8f,
            rungColor);
    }

    DrawLineEx(
        (Vector2){s.x - n.x * off, s.y - n.y * off},
        (Vector2){e.x - n.x * off, e.y - n.y * off},
        rail, railColor);

    DrawLineEx(
        (Vector2){s.x + n.x * off, s.y + n.y * off},
        (Vector2){e.x + n.x * off, e.y + n.y * off},
        rail, railColor);
}

static void DrawSnakeShape(
    const Layout *L, int head, int tail, Color base)
{
    float cell = L->boardSize / (float)SNAKE_BOARD_N;

    Vector2 h = SnakeCellCenter(L, head);
    Vector2 t = SnakeCellCenter(L, tail);

    float dx = t.x - h.x;
    float dy = t.y - h.y;
    float len = sqrtf(dx * dx + dy * dy);

    if (len < 1.0f)
        return;

    Vector2 u = {dx / len, dy / len};
    Vector2 n = {-u.y, u.x};

    int waves = (int)(len / (cell * 1.8f) + 0.5f);
    if (waves < 2) waves = 2;

    float amp = cell * 0.32f;

    Vector2 pts[SNAKE_SEGS + 1];
    float width[SNAKE_SEGS + 1];

    for (int i = 0; i <= SNAKE_SEGS; i++) {
        float s = (float)i / (float)SNAKE_SEGS;
        float off = sinf(s * PI * (float)waves) * amp;

        pts[i] = (Vector2) {
            h.x + dx * s + n.x * off,
            h.y + dy * s + n.y * off
        };

        width[i] = cell * (0.34f - 0.27f * s);
    }

    Color dark = ColorMix(base, BLACK, 0.50f);
    Color light = ColorMix(base, WHITE, 0.35f);

    /* Dark outline pass */
    for (int i = 0; i < SNAKE_SEGS; i++) {
        DrawLineEx(pts[i], pts[i + 1], width[i] + 4.0f, dark);
        DrawCircleV(pts[i + 1], width[i + 1] * 0.5f + 2.0f, dark);
    }

    /* Colored body with banding */
    for (int i = 0; i < SNAKE_SEGS; i++) {
        Color c = ((i / 3) % 2 == 0) ? base : light;

        DrawLineEx(pts[i], pts[i + 1], width[i], c);
        DrawCircleV(pts[i + 1], width[i + 1] * 0.5f, c);
    }

    /* Head */
    Vector2 f = {pts[0].x - pts[1].x, pts[0].y - pts[1].y};
    float fl = sqrtf(f.x * f.x + f.y * f.y);

    if (fl > 0.001f) {
        f.x /= fl;
        f.y /= fl;
    } else {
        f = (Vector2){0.0f, -1.0f};
    }

    Vector2 g = {-f.y, f.x};
    float hr = width[0] * 0.66f;

    /* Tongue */
    Vector2 tb = {pts[0].x + f.x * hr, pts[0].y + f.y * hr};
    Vector2 tt = {pts[0].x + f.x * (hr + cell * 0.20f),
                  pts[0].y + f.y * (hr + cell * 0.20f)};

    DrawLineEx(tb, tt, 2.0f, (Color){220, 40, 60, 255});
    DrawLineEx(tt,
        (Vector2){tt.x + f.x * cell * 0.07f + g.x * cell * 0.06f,
                  tt.y + f.y * cell * 0.07f + g.y * cell * 0.06f},
        2.0f, (Color){220, 40, 60, 255});
    DrawLineEx(tt,
        (Vector2){tt.x + f.x * cell * 0.07f - g.x * cell * 0.06f,
                  tt.y + f.y * cell * 0.07f - g.y * cell * 0.06f},
        2.0f, (Color){220, 40, 60, 255});

    DrawCircleV(pts[0], hr + 2.0f, dark);
    DrawCircleV(pts[0], hr, base);

    for (int side = -1; side <= 1; side += 2) {
        Vector2 eye = {
            pts[0].x + f.x * hr * 0.30f + g.x * hr * 0.50f * (float)side,
            pts[0].y + f.y * hr * 0.30f + g.y * hr * 0.50f * (float)side
        };

        DrawCircleV(eye, hr * 0.30f, WHITE);
        DrawCircleV(
            (Vector2){eye.x + f.x * hr * 0.08f, eye.y + f.y * hr * 0.08f},
            hr * 0.15f,
            (Color){20, 20, 30, 255});
    }
}

static void DrawSnakePiece(
    Vector2 c, float r, Color color, Color dark, bool glow)
{
    if (glow) {
        float pulse = 0.5f + 0.5f * sinf((float)GetTime() * 7.0f);

        DrawRing(c, r * 1.15f, r * (1.28f + pulse * 0.08f),
                 0, 360, 36, GOLD);
    }

    DrawCircleV((Vector2){c.x + 2, c.y + 4}, r, Fade(BLACK, 0.30f));
    DrawCircleV(c, r, dark);
    DrawCircleV(c, r * 0.84f, color);
    DrawCircleV(
        (Vector2){c.x - r * 0.27f, c.y - r * 0.30f},
        r * 0.23f,
        Fade(WHITE, 0.50f));
}

static void DrawSnakeCard(const Game *game, int id, Rectangle r)
{
    const SnakeGame *s = &game->snake;
    const Player *p = &game->players[id];

    bool active = s->state != SN_OVER && s->current == id;

    DrawShadowRect(r, 0.12f, 0.35f);

    DrawRectangleRounded(
        r, 0.12f, 12,
        active ? Fade(p->color, 0.18f) : Fade(PANEL_2, 0.92f));

    DrawRectangleRoundedLinesEx(
        r, 0.12f, 12,
        active ? 3.0f : 1.0f,
        active ? Fade(p->color, 0.90f) : Fade(WHITE, 0.10f));

    DrawCircleV(
        (Vector2){r.x + 24.0f, r.y + r.height * 0.5f},
        12.0f, p->color);

    DrawCircleV(
        (Vector2){r.x + 21.0f, r.y + r.height * 0.5f - 4.0f},
        3.0f, Fade(WHITE, 0.65f));

    DrawText(p->name, (int)(r.x + 46), (int)(r.y + 10), 18, WHITE_SOFT);

    DrawYouTag(game, id, r, p->name);

    DrawText(p->subtitle, (int)(r.x + 46), (int)(r.y + 32), 10, TEXT_MUTED);

    char status[64];
    if (s->pos[id] == 0)
        snprintf(status, sizeof(status), "Roll a 1 to start");
    else
        snprintf(status, sizeof(status),
                 "Square %d / %d", s->pos[id], SNAKE_LAST);

    DrawText(
        status,
        (int)(r.x + 46), (int)(r.y + 48), 9,
        active ? Fade(p->color, 0.95f) : TEXT_MUTED);

    Rectangle bar = {r.x + 46, r.y + r.height - 7, 100.0f, 3.0f};

    DrawRectangleRounded(bar, 0.5f, 4, Fade(WHITE, 0.10f));

    Rectangle progress = bar;
    progress.width *= (float)s->pos[id] / (float)SNAKE_LAST;

    DrawRectangleRounded(progress, 0.5f, 4, p->color);

    if (active) {
        const char *badge = "YOUR TURN";

        if (s->state == SN_ROLLING)
            badge = "ROLLING";
        else if (s->vsComputer && id == 1 && s->state == SN_WAIT_ROLL)
            badge = "THINKING";
        else if (gNet.role != NET_OFF && !NetIsMe(game, id))
            badge = "THEIR TURN";

        DrawRectangleRounded(
            (Rectangle){r.x + 180, r.y + 15, 82, 24},
            0.5f, 8, Fade(p->color, 0.20f));

        DrawCenteredText(badge, r.x + 221, r.y + 20, 9, p->color);
    }
}

static void DrawSnakes(const Game *game)
{
    const Layout *L = &game->layout;
    const SnakeGame *s = &game->snake;

    float cell = L->boardSize / (float)SNAKE_BOARD_N;

    Rectangle board = {
        L->boardOrigin.x, L->boardOrigin.y,
        L->boardSize, L->boardSize
    };

    DrawRectangleRounded(
        (Rectangle){board.x + 8, board.y + 10, board.width, board.height},
        0.025f, 12, Fade(BLACK, 0.40f));

    DrawRectangleRounded(board, 0.025f, 12, BOARD_WHITE);

    /* Cells */
    int numSize = (int)(cell * 0.20f);
    if (numSize < 9) numSize = 9;

    for (int n = 1; n <= SNAKE_LAST; n++) {
        Vector2 c = SnakeCellCenter(L, n);

        int idx = n - 1;
        int row = idx / SNAKE_BOARD_N;
        int col = idx % SNAKE_BOARD_N;
        if (row % 2 == 1) col = SNAKE_BOARD_N - 1 - col;

        Color fill = ((row + col) % 2 == 0)
            ? (Color){226, 236, 252, 255}
            : (Color){206, 220, 246, 255};

        if (n == 1)
            fill = (Color){190, 238, 214, 255};
        else if (n == SNAKE_LAST)
            fill = (Color){254, 236, 160, 255};

        Rectangle rc = {c.x - cell * 0.5f, c.y - cell * 0.5f, cell, cell};

        DrawRectangleRec(rc, fill);
        DrawRectangleLinesEx(rc, 1.0f, Fade(BOARD_LINE, 0.90f));

        DrawText(
            TextFormat("%d", n),
            (int)(rc.x + 4), (int)(rc.y + 3),
            numSize,
            Fade((Color){70, 82, 115, 255}, 0.85f));

        if (n == SNAKE_LAST)
            DrawStar((Vector2){c.x, c.y + cell * 0.12f},
                     cell * 0.26f, GOLD);

        if (n == 1)
            DrawCenteredText("START", c.x, c.y + cell * 0.10f,
                             (int)fmaxf(9.0f, cell * 0.17f),
                             (Color){20, 120, 80, 255});
    }

    /* Ladders, then snakes on top */
    for (int i = 0; i < NUM_LADDERS; i++)
        DrawLadderShape(L, LADDERS[i].from, LADDERS[i].to);

    static const Color SNAKE_COLORS[NUM_SNAKES] = {
        {46, 160, 80, 255},   {231, 76, 60, 255},
        {155, 89, 182, 255},  {230, 126, 34, 255},
        {26, 188, 156, 255},  {233, 30, 99, 255},
        {121, 85, 72, 255},   {120, 144, 20, 255}
    };

    for (int i = 0; i < NUM_SNAKES; i++)
        DrawSnakeShape(L, SNAKES[i].from, SNAKES[i].to, SNAKE_COLORS[i]);

    DrawRectangleRoundedLinesEx(
        board, 0.025f, 12, 3.0f,
        Fade((Color){110, 120, 145, 255}, 0.75f));

    /* Pieces */
    for (int p = 0; p < 2; p++) {
        Vector2 c;

        if (s->pos[p] == 0)
            continue;       /* waiting for a 1 or a 6 */

        if (s->state == SN_SLIDING && s->current == p) {
            float t = s->slideT;
            if (t > 1.0f) t = 1.0f;
            t = t * t * (3.0f - 2.0f * t);

            Vector2 a = SnakeCellCenter(L, s->slideFrom);
            Vector2 b = SnakeCellCenter(L, s->slideTo);

            c = (Vector2){a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t};
        } else {
            c = SnakeCellCenter(L, s->pos[p]);

            if (s->pos[0] == s->pos[1])
                c.x += (p == 0 ? -1.0f : 1.0f) * cell * 0.17f;
        }

        bool glow = s->state == SN_WAIT_ROLL && s->current == p;

        DrawSnakePiece(
            c,
            cell * (s->pos[0] == s->pos[1] ? 0.19f : 0.24f),
            game->players[p].color,
            game->players[p].darkColor,
            glow);
    }

    /* Player cards, dice, roll button */
    for (int p = 0; p < 2; p++) {
        DrawSnakeCard(game, p, L->playerCard[p]);

        bool activeDie = s->state != SN_OVER && s->current == p;

        int shown =
            (s->state == SN_ROLLING && s->current == p)
                ? s->shown
                : s->playerDice[p];

        DrawCenteredText(
            "DICE",
            L->diceBox[p].x + L->diceBox[p].width * 0.5f,
            L->diceBox[p].y - 7.0f,
            7,
            activeDie ? game->players[p].color : TEXT_MUTED);

        DrawDice(
            L->diceBox[p],
            shown,
            game->players[p].color,
            activeDie && s->state == SN_ROLLING,
            activeDie);
    }

    bool rollEnabled =
        s->state == SN_WAIT_ROLL &&
        !(s->vsComputer && s->current == 1) &&
        LocalCanAct(game, s->current);

    DrawModernButton(
        L->rollButton,
        rollEnabled ? "ROLL DICE" : "WAIT...",
        game->players[s->current].color,
        rollEnabled,
        15);

    DrawSideBar(L);

    /* Toast message over the board */
    if (s->toastTimer > 0.0f && s->state != SN_OVER) {
        float a = s->toastTimer > 0.4f ? 1.0f : s->toastTimer / 0.4f;
        int fs = 20;
        int tw = MeasureText(s->toast, fs);

        Rectangle pill = {
            board.x + board.width * 0.5f - (float)tw * 0.5f - 18.0f,
            board.y + board.height * 0.5f - 18.0f,
            (float)tw + 36.0f,
            36.0f
        };

        DrawRectangleRounded(pill, 0.5f, 10, Fade((Color){20, 26, 46, 255}, 0.88f * a));
        DrawRectangleRoundedLinesEx(pill, 0.5f, 10, 2.0f, Fade(GOLD, a));

        DrawText(
            s->toast,
            (int)(pill.x + 18.0f), (int)(pill.y + 8.0f),
            fs, Fade(WHITE_SOFT, a));
    }
}

/* ================================================================
   MENU
   ================================================================ */

/* Body of the hosting / joining screen (drawn on top of the menu
   background, in the place where the menu buttons normally are). */
static void DrawLobbyBody(const Game *game)
{
    const Layout *L = &game->layout;

    int sw = GetScreenWidth();
    float cx = (float)sw * 0.5f;
    float y = L->menuBtn[0].y;

    Rectangle back = L->menuBtn[4];

    switch (gNet.phase) {

        case NP_HOST_WAIT: {
            const char *kind = "LUDO  2 PLAYERS";

            if (gNet.hostKind == KIND_SNAKES)
                kind = "SNAKES & LADDERS  2 PLAYERS";
            else if (gNet.hostCount == 4 && gNet.hostTeams)
                kind = "LUDO  TEAM MODE  2 vs 2";
            else if (gNet.hostCount == 4)
                kind = "LUDO  4 PLAYERS";

            int needed = gNet.hostCount - 1;
            int joined = 0;

            for (int i = 0; i < needed; i++)
                if (gNet.conns[i].used)
                    joined++;

            DrawCenteredText(
                TextFormat("HOSTING:  %s", kind),
                cx, y, 24, WHITE_SOFT);

            DrawCenteredText(
                "Friends: PLAY ON WIFI > JOIN A GAME, then type this IP address:",
                cx, y + 38, 15, TEXT_MUTED);

            if (gNet.localIpCount == 0) {
                DrawCenteredText(
                    "(IP not found - look at ipconfig / ifconfig)",
                    cx, y + 74, 20, ORANGE);
            } else {
                for (int i = 0; i < gNet.localIpCount; i++)
                    DrawCenteredText(
                        gNet.localIps[i],
                        cx, y + 66 + (float)i * 36.0f, 30, GOLD);
            }

            DrawCenteredText(
                TextFormat("Players joined:  %d / %d", joined, needed),
                cx, y + 184, 20, CYAN);

            DrawCenteredText(
                "Same Wi-Fi or same hotspot.  Port 7777.  The game starts automatically.",
                cx, y + 216, 13, TEXT_MUTED);

            DrawModernButton(back, "CANCEL", GREY_BTN, true, 22);
            break;
        }

        case NP_JOIN_INPUT: {
            Rectangle box = L->menuBtn[1];

            DrawCenteredText("JOIN A GAME", cx, y, 24, WHITE_SOFT);

            DrawCenteredText(
                "Type the IP address shown on the host's screen:",
                cx, y + 34, 15, TEXT_MUTED);

            box.x -= 40.0f;
            box.width += 80.0f;

            DrawRectangleRounded(box, 0.25f, 12, PANEL_2);
            DrawRectangleRoundedLinesEx(box, 0.25f, 12, 2.0f, CYAN);

            bool blink = ((int)(GetTime() * 2.0) % 2) == 0;
            char shown[40];

            snprintf(shown, sizeof(shown), "%s%s",
                     gNet.ip, blink ? "|" : " ");

            DrawCenteredText(
                shown,
                cx, box.y + (box.height - 28.0f) * 0.5f, 28, WHITE_SOFT);

            DrawCenteredText(
                "Same Wi-Fi / hotspot as the host.  Ctrl+V pastes.  ENTER connects.",
                cx, L->menuBtn[2].y + 14.0f, 13, TEXT_MUTED);

            DrawModernButton(
                L->menuBtn[3], "CONNECT", GREEN, true, 22);
            DrawModernButton(back, "BACK", GREY_BTN, true, 22);
            break;
        }

        case NP_CONNECTING:
            DrawCenteredText(
                TextFormat("Connecting to  %s ...", gNet.ip),
                cx, y + 20, 26, WHITE_SOFT);

            DrawCenteredText(
                "Please wait",
                cx, y + 62, 16, TEXT_MUTED);

            DrawModernButton(back, "CANCEL", GREY_BTN, true, 22);
            break;

        case NP_CLIENT_WAIT:
        default: {
            int pid = SeatToPlayerId(
                gNet.hostKind, gNet.hostCount, gNet.seat);

            const char *names[4] = { "RED", "BLUE", "GREEN", "YELLOW" };
            Color cols[4] = { RED, BLUE, GREEN, GOLD };

            DrawCenteredText("CONNECTED!", cx, y, 30, GREEN);

            DrawCircleV(
                (Vector2){cx, y + 76.0f}, 16.0f, cols[pid]);

            DrawCenteredText(
                TextFormat("You are Player %d  (%s)",
                           gNet.seat + 1, names[pid]),
                cx, y + 104, 22, WHITE_SOFT);

            DrawCenteredText(
                "Waiting for the other players / the host to start...",
                cx, y + 146, 16, TEXT_MUTED);

            DrawModernButton(back, "LEAVE", GREY_BTN, true, 22);
            break;
        }
    }
}

static void DrawMenu(const Game *game)
{
    int sw = GetScreenWidth();
    int sh = GetScreenHeight();

    DrawRectangle(
        0, 0, sw, sh,
        Fade(BLACK, 0.76f));

    float pulse =
        0.5f +
        0.5f * sinf(
            (float)GetTime() * 2.0f);

    /* Decorative circles */
    DrawCircle(
        sw / 2 - 310,
        sh / 2 - 50,
        180,
        Fade(RED, 0.08f));

    DrawCircle(
        sw / 2 + 310,
        sh / 2 - 50,
        180,
        Fade(BLUE, 0.08f));

    DrawCenteredText(
        "LUDO",
        sw * 0.5f,
        sh * 0.18f,
        92,
        WHITE_SOFT);

    DrawCenteredText(
        "DUEL",
        sw * 0.5f,
        sh * 0.18f + 91,
        22,
        CYAN);

    const char *sub = "Choose a game";

    if (game->state == STATE_NET_LOBBY)
        sub = "PLAY ON WIFI / HOTSPOT";
    else if (game->menuPage == MENU_LUDO)
        sub = "LUDO  -  choose a mode";
    else if (game->menuPage == MENU_SNAKES)
        sub = "SNAKES & LADDERS  -  choose a mode";
    else if (game->menuPage == MENU_ONLINE)
        sub = "PLAY ON WIFI / HOTSPOT  -  no internet needed";

    DrawCenteredText(
        sub,
        sw * 0.5f,
        sh * 0.18f + 130,
        18,
        TEXT_MUTED);

    /* Logo dots */
    Color dots[4] = {RED, BLUE, GOLD, GREEN};

    for (int i = 0; i < 4; i++) {
        float a =
            (float)GetTime() * 0.8f +
            i * PI / 2.0f;

        Vector2 c = {
            sw * 0.5f + cosf(a) * 110.0f,
            sh * 0.18f + 42.0f +
            sinf(a) * 22.0f
        };

        DrawCircleV(
            c,
            9.0f + pulse * 2.0f,
            dots[i]);
    }

    if (game->state == STATE_NET_LOBBY) {
        DrawLobbyBody(game);
    } else {
        static const char *MAIN_LABELS[4] =
            {"LUDO", "SNAKES & LADDERS", "PLAY ON WIFI", "EXIT"};
        static const Color MAIN_COLORS[4] =
            {{34, 197, 134, 255}, {147, 51, 234, 255},
             {56, 189, 248, 255}, {239, 68, 68, 255}};

        static const char *LUDO_LABELS[5] =
            {"2 PLAYERS", "4 PLAYERS", "TEAM MODE  2 vs 2",
             "VS COMPUTER", "BACK"};
        static const Color LUDO_COLORS[5] =
            {{34, 197, 134, 255}, {59, 130, 246, 255}, {147, 51, 234, 255},
             {251, 146, 60, 255}, {82, 94, 125, 255}};

        static const char *SNAKE_LABELS[3] =
            {"2 PLAYERS", "VS COMPUTER", "BACK"};
        static const Color SNAKE_COLORS_M[3] =
            {{34, 197, 134, 255}, {251, 146, 60, 255}, {82, 94, 125, 255}};

        static const char *ONLINE_LABELS[6] =
            {"HOST  LUDO 2 PLAYERS", "HOST  LUDO 4 PLAYERS",
             "HOST  LUDO TEAM 2v2", "HOST  SNAKES & LADDERS",
             "JOIN A GAME", "BACK"};
        static const Color ONLINE_COLORS[6] =
            {{34, 197, 134, 255}, {59, 130, 246, 255}, {147, 51, 234, 255},
             {251, 146, 60, 255}, {56, 189, 248, 255}, {82, 94, 125, 255}};

        const char **labels = MAIN_LABELS;
        const Color *colors = MAIN_COLORS;
        int fontSize = 22;

        if (game->menuPage == MENU_LUDO) {
            labels = LUDO_LABELS;
            colors = LUDO_COLORS;
        } else if (game->menuPage == MENU_SNAKES) {
            labels = SNAKE_LABELS;
            colors = SNAKE_COLORS_M;
        } else if (game->menuPage == MENU_ONLINE) {
            labels = ONLINE_LABELS;
            colors = ONLINE_COLORS;
            fontSize = 19;
        }

        int count = MenuButtonCount(game->menuPage);

        for (int i = 0; i < count; i++) {
            DrawModernButton(
                game->layout.menuBtn[i],
                labels[i],
                colors[i],
                true,
                fontSize);
        }

        DrawCenteredText(
            "ENTER  =  Ludo 2 Players     4  =  Ludo 4 Players     M  =  Mute",
            sw * 0.5f,
            sh - 58,
            14,
            TEXT_MUTED);
    }

    /* Short messages ("could not connect", "host left" ...) */
    if (gNet.noticeTimer > 0.0f) {
        float a = gNet.noticeTimer > 0.5f ? 1.0f : gNet.noticeTimer / 0.5f;

        DrawCenteredText(
            gNet.notice,
            sw * 0.5f,
            sh - 92,
            18,
            Fade(ORANGE, a));
    }
}

/* ================================================================
   VICTORY
   ================================================================ */

static void DrawVictory(const Game *game)
{
    int sw = GetScreenWidth();
    int sh = GetScreenHeight();

    char name[48];
    Color color;
    const char *line;

    if (game->state == STATE_SNAKES) {
        const Player *w = &game->players[game->snake.winner];

        snprintf(name, sizeof(name), "%s", w->name);
        color = w->color;
        line = "Reached square 100 first!";
    } else if (game->teamMode) {
        const Player *w = &game->players[game->winner];
        int a = game->winner;
        int b = TeammateOf(game->winner);

        if (a > b) { int tmp = a; a = b; b = tmp; }

        snprintf(name, sizeof(name), "TEAM %s & %s",
                 game->players[a].name,
                 game->players[b].name);
        color = w->color;
        line = "All eight tokens reached HOME.";
    } else {
        const Player *w = &game->players[game->winner];

        snprintf(name, sizeof(name), "%s", w->name);
        color = w->color;
        line = "All four tokens reached HOME.";
    }

    DrawRectangle(
        0, 0, sw, sh,
        Fade(BLACK, 0.70f));

    DrawShadowRect(
        game->layout.winBox,
        0.08f,
        0.50f);

    DrawRectangleRounded(
        game->layout.winBox,
        0.08f,
        12,
        PANEL);

    DrawRectangleRoundedLinesEx(
        game->layout.winBox,
        0.08f,
        12,
        3.0f,
        color);

    DrawCenteredText(
        "VICTORY!",
        sw * 0.5f,
        game->layout.winBox.y + 38,
        54,
        GOLD);

    DrawCircleV(
        (Vector2){
            sw * 0.5f,
            game->layout.winBox.y + 125
        },
        32,
        color);

    DrawCenteredText(
        name,
        sw * 0.5f,
        game->layout.winBox.y + 169,
        34,
        color);

    DrawCenteredText(
        line,
        sw * 0.5f,
        game->layout.winBox.y + 218,
        17,
        TEXT_MUTED);

    DrawModernButton(
        game->layout.winRestartButton,
        "PLAY AGAIN",
        GREEN,
        true,
        16);

    DrawModernButton(
        game->layout.winMenuButton,
        "MAIN MENU",
        GREY_BTN,
        true,
        16);
}

/* ================================================================
   COMPLETE FRAME
   ================================================================ */

static void DrawLudoBackground(int sw, int sh)
{
    /* Clean dark-blue gradient only. No vector pattern, circles,
       decorative blobs, or extra background shapes. */
    DrawVerticalGradient(
        sw,
        sh,
        (Color){8, 18, 38, 255},
        (Color){22, 48, 86, 255});
}

static void DrawGame(const Game *game)
{
    int sw = GetScreenWidth();
    int sh = GetScreenHeight();

    DrawLudoBackground(sw, sh);

    if (game->state == STATE_SNAKES) {
        DrawSnakes(game);

        if (game->snake.state == SN_OVER)
            DrawVictory(game);
    } else {
        DrawBoard(game);
        DrawTokens(game);

        if (game->state == STATE_MENU ||
            game->state == STATE_NET_LOBBY) {
            DrawMenu(game);
        } else {
            DrawPanel(game);

            if (game->state == STATE_GAME_OVER)
                DrawVictory(game);
        }
    }

    if (gMuted)
        DrawText("MUTED  (M)", 10, sh - 18, 10, TEXT_MUTED);
}

/* ================================================================
   MAIN
   ================================================================ */

int main(void)
{
    SetConfigFlags(
        FLAG_WINDOW_RESIZABLE |
        FLAG_MSAA_4X_HINT |
        FLAG_VSYNC_HINT);

    InitWindow(
        SCREEN_W,
        SCREEN_H,
        "Modern Ludo Duel - raylib");

    SetWindowMinSize(1050, 700);

    SetExitKey(KEY_NULL);
    SetTargetFPS(60);

    Game game;

    InitGame(&game);
    InitSounds();

    while (!WindowShouldClose() &&
           !game.exitRequested) {

        UpdateGame(&game);

        BeginDrawing();

        DrawGame(&game);

        EndDrawing();
    }

    NetStop();
    NetShutdownSystem();

    FreeSounds();
    CloseWindow();

    return 0;
}
